export const PWM_QUESTIONS = [{"id":1,"s":1,"q":"What is the main difference between managing plastic waste and merely disposing of it?","o":["Management means storing waste, while disposal means collecting it.","Management covers segregation, collection, recycling, recovery and safe disposal, while disposal is only one part of the process.","Management means burning waste, while disposal means sorting it.","Management and disposal mean exactly the same thing."],"a":1,"e":""},{"id":2,"s":1,"q":"What is the purpose of maintaining plastic waste records?","o":["To replace the need for registration.","To avoid submitting any required reports.","To track waste quantities, movement and processing, and demonstrate compliance.","To record only the colour of discarded plastics."],"a":2,"e":""},{"id":3,"s":1,"q":"What is the purpose of marking and labelling plastic packaging?","o":["To provide required identification, material and compliance information.","To guarantee that every plastic package is biodegradable.","To exempt the packaging from EPR obligations.","To make all plastic packaging suitable for food contact."],"a":0,"e":""},{"id":4,"s":1,"q":"Why is open burning of plastic waste an environmental concern?","o":["It converts all plastic waste into useful compost.","It removes pollutants from the surrounding air.","It safely recycles plastic without processing equipment.","It can release harmful pollutants, affecting air quality, human health and the environment."],"a":3,"e":""},{"id":5,"s":1,"q":"What is meant by environmentally sound plastic waste management?","o":["Dumping plastic waste in an unused open area.","Handling and processing plastic waste in ways that protect human health and the environment.","Mixing plastic waste with food waste before disposal.","Burning plastic waste outdoors to reduce its volume."],"a":1,"e":""},{"id":6,"s":1,"q":"Why is traceability important in plastic waste management?","o":["To exempt waste transfers from regulatory review.","To verify waste origin and final processing.","To replace evidence of actual waste processing.","To classify all collected waste as recycled."],"a":1,"e":"A traceable chain shows where the waste came from, who handled it and what ultimately happened to it."},{"id":7,"s":1,"q":"What is an EPR certificate?","o":["A certificate recording eligible processing under EPR.","A certificate confirming a company's tax registration.","A certificate approving the packaging's food-contact suitability.","A certificate granting permission to manufacture packaging."],"a":0,"e":"The certificate concerns eligible processing credited through the EPR system; it is different from registration, tax or product-quality certification."},{"id":8,"s":1,"q":"What is an annual return under the EPR framework?","o":["A yearly application for a new trademark.","A yearly submission of prescribed compliance information.","A yearly replacement for the registration certificate.","A yearly estimate submitted instead of records."],"a":1,"e":"An annual return reports the relevant year's activities and compliance information, rather than simply applying for permission to operate."},{"id":9,"s":1,"q":"What is an EPR target?","o":["A voluntary forecast of annual packaging sales.","A prescribed obligation for the relevant period.","A registration fee based on company turnover.","A product standard for measuring packaging thickness."],"a":1,"e":"The applicable target depends on the entity's role, the packaging category, the period and the prescribed calculation."},{"id":10,"s":1,"q":"Why is registration important under the PWM Rules?","o":["To prove every annual target is fulfilled.","To replace all required environmental operating consents.","To approve every plastic item for sale.","To establish the covered entity's registered status."],"a":3,"e":"Registration establishes the entity's recorded status. Actual target achievement and ongoing reporting still require separate evidence."},{"id":11,"s":1,"q":"What is the purpose of the centralised online portal under the PWM framework?","o":["To administer relevant registration and compliance information.","To grant automatic exemptions from packaging obligations.","To replace the rules with voluntary declarations.","To certify every submitted processing claim automatically."],"a":0,"e":"The portal brings relevant information into one system so authorities can administer registrations, transactions and reporting."},{"id":12,"s":1,"q":"What is the role of a local body in plastic waste management?","o":["To notify amendments to national environmental legislation.","To issue the applicable national packaging standards.","To set category-wise targets for every importer.","To organise local waste management and enforcement."],"a":3,"e":"Local bodies support the waste-management system within their jurisdiction and exercise the enforcement powers assigned to them."},{"id":13,"s":1,"q":"What is the role of a Pollution Control Committee?","o":["Assigned pollution-control functions in a Union territory.","Assigned trademark-registration functions for all packaged goods.","Assigned customs-assessment functions for imported plastic materials.","Assigned product-pricing functions for recycled plastic resin."],"a":0,"e":"A Pollution Control Committee performs the assigned pollution-control role for the relevant Union territory."},{"id":14,"s":1,"q":"What is the role of a State Pollution Control Board in plastic waste management?","o":["Automatic approval of every locally manufactured package.","Exclusive responsibility for notifying national PWM amendments.","Assigned state-level registration, oversight and enforcement functions.","Replacement of all municipal waste-management responsibilities."],"a":2,"e":"State-level functions include oversight of covered facilities and activities within the authority's jurisdiction."},{"id":15,"s":1,"q":"What is the role of the Central Pollution Control Board in PWM implementation?","o":["Direct collection of every household's plastic waste.","National coordination and assigned central compliance functions.","Automatic approval of all uploaded compliance certificates.","Exclusive operation of every registered recycling facility."],"a":1,"e":"CPCB performs national coordination and the central functions assigned by the rules; local operations remain distributed among relevant authorities and entities."},{"id":16,"s":1,"q":"What is waste-to-oil conversion?","o":["Converting plastic waste into an oil output.","Removing oil residues from empty plastic packaging.","Refilling used containers with a liquid product.","Blending virgin resin with industrial lubricating oil."],"a":0,"e":"The process changes plastic waste into an oil output; merely collecting or washing a bottle does not perform this conversion."},{"id":17,"s":1,"q":"What is waste-to-energy processing?","o":["Transporting waste to a temporary storage site.","Sorting waste into separate plastic resin groups.","Washing waste before selling it as scrap.","Processing waste to recover usable energy."],"a":3,"e":"The defining outcome is usable energy, rather than simply storing or transporting the waste."},{"id":18,"s":1,"q":"What is co-processing of plastic waste?","o":["Storing collected waste within an industrial compound.","Using suitable waste in an industrial process.","Distributing reusable packaging to an industrial customer.","Selling virgin resin to an industrial manufacturer."],"a":1,"e":"In an appropriate industrial process, waste can substitute for conventional fuel or resources, subject to the relevant requirements."},{"id":19,"s":1,"q":"What is the difference between recycling and end-of-life disposal?","o":["Identical activities with entirely interchangeable compliance evidence.","Distinct processing routes with separate compliance accounting.","Different names for collecting the same waste.","Different methods of reusing unchanged plastic containers."],"a":1,"e":"The relevant EPR provision and specific processing route determine accounting treatment; the amended definitions should not be reduced to a single blanket rule."},{"id":20,"s":1,"q":"What is the difference between compostable and biodegradable plastics?","o":["Composting and biodegradation require different specified conditions.","Both guarantee immediate breakdown in natural environments.","Both establish the same unrestricted food-contact suitability.","Compostability depends solely on using plant-based resin."],"a":0,"e":"A material's claimed performance must be linked to defined conditions. Neither term guarantees rapid degradation in every natural environment."},{"id":21,"s":1,"q":"What is the difference between recycling and reuse?","o":["Reuse melts objects; recycling retains their structure.","Reuse means collection; recycling means temporary storage.","Reuse retains objects; recycling reprocesses waste.","Reuse and recycling describe identical processing activities."],"a":2,"e":"Refilling an unchanged container is reuse; melting and reprocessing discarded plastic into a new article is material recycling."},{"id":22,"s":1,"q":"What is the difference between plastic waste collection and plastic waste processing?","o":["Collection certifies recycling; processing certifies brand ownership.","Collection manufactures resin; processing merely records dispatch.","Collection gathers waste; processing treats the material.","Collection and processing always establish identical outcomes."],"a":2,"e":"Gathering waste is an upstream step. Evidence that waste was gathered does not by itself demonstrate treatment or recovery."},{"id":23,"s":1,"q":"Why is segregation important in plastic waste management?","o":["To establish that every material is compostable.","To remove all subsequent processing-evidence requirements.","To reduce contamination and improve processing suitability.","To guarantee complete recovery without process losses."],"a":2,"e":"Separating incompatible materials and contaminants improves the suitability of waste for the intended processing route."},{"id":24,"s":1,"q":"What is the purpose of plastic waste collection?","o":["To gather waste for appropriate subsequent handling.","To establish full recycling without processing evidence.","To replace every generator's waste-management responsibilities.","To approve the collected material for food-contact."],"a":0,"e":"Collection connects waste generators with appropriate handling channels, but collection alone does not prove final processing."},{"id":25,"s":1,"q":"What is Extended Producer Responsibility?","o":["Voluntary responsibility limited to product marketing activities.","Prescribed responsibility for environmentally sound product-waste management.","Exclusive responsibility assigned to the final consumer.","Automatic exemption obtained by paying disposal contractors."],"a":1,"e":"EPR extends the relevant responsibility beyond making or selling a product to its prescribed post-use management obligations."},{"id":26,"s":1,"q":"What is flexible plastic packaging?","o":["Plastic packaging defined by its green colour.","Plastic packaging that always contains recycled resin.","Plastic packaging that bends or changes shape.","Plastic packaging designed to retain its shape."],"a":2,"e":"Films and pouches can bend or change shape easily, unlike bottles or containers designed to retain their form."},{"id":27,"s":1,"q":"What is rigid plastic packaging?","o":["Plastic packaging defined by its recycled percentage.","Plastic packaging defined by its brand ownership.","Plastic packaging designed to retain its shape.","Plastic packaging intended exclusively for industrial composting."],"a":2,"e":"Typical examples include qualifying plastic bottles, jars and drums; the term describes the packaging format rather than its colour."},{"id":28,"s":1,"q":"What is multilayered plastic packaging?","o":["Packaging combining several layers made entirely of plastic.","Packaging containing several individually packed consumer products.","Packaging carrying several different registered brand labels.","Packaging combining plastic and non-plastic material layers."],"a":3,"e":"For the relevant multilayered category, the presence of a non-plastic layer distinguishes it from an all-plastic flexible laminate."},{"id":29,"s":1,"q":"What is a plastic carry bag?","o":["Any wrapper integral to a sealed consumer product.","Any container used to store plastic raw material.","Any film used during production of plastic packaging.","A qualifying bag for carrying or dispensing goods."],"a":3,"e":"The legal definition distinguishes a carry bag from packaging that is an integral part of a sealed product."},{"id":30,"s":1,"q":"What is single-use plastic?","o":["Plastic prohibited regardless of its intended use.","Plastic manufactured exclusively from recycled waste material.","Plastic unable to undergo any processing treatment.","Plastic intended for one-time use before discard."],"a":3,"e":"Single-use describes intended use. Whether an item is prohibited requires a separate check against the specified legal restrictions."},{"id":31,"s":1,"q":"What is biodegradable plastic?","o":["Plastic that merely fragments into smaller visible pieces.","Plastic automatically certified through plant-based material sourcing.","Plastic guaranteed to degrade equally in every environment.","Plastic meeting specified environment-dependent biological degradation requirements."],"a":3,"e":"Breaking into smaller fragments or microplastics alone does not demonstrate conformity with the biodegradable-plastic definition."},{"id":32,"s":1,"q":"What is compostable plastic?","o":["Plastic containing the prescribed minimum recycled-material percentage.","Plastic fragmented into particles through outdoor weather exposure.","Plastic meeting the applicable specified compostability requirements.","Plastic certified for unrestricted disposal in natural environments."],"a":2,"e":"The claim must be supported by the applicable standard and certification, and the required industrial-composting information matters."},{"id":33,"s":1,"q":"What is recycled plastic content?","o":["Packaging waste collected after the consumer's use.","Virgin plastic purchased for manufacturing new packaging.","Plastic waste transferred to a collection contractor.","Recycled plastic incorporated into packaging or products."],"a":3,"e":"Recycled content describes material incorporated into the article; it is different from the amount collected for recycling afterward."},{"id":34,"s":1,"q":"What is virgin plastic?","o":["Plastic material not previously used or recycled.","Plastic material recovered from discarded consumer bottles.","Plastic material collected from manufacturing scrap streams.","Plastic material reprocessed into new packaging granules."],"a":0,"e":"Virgin material has not been recovered through recycling of previously used or waste plastic material."},{"id":35,"s":1,"q":"What is meant by a seller under the 2026 amendment?","o":["A seller of covered plastic raw materials or intermediates.","A collector transporting discarded packaging to sorting facilities.","A retailer selling products packed in plastic containers.","A consultant preparing compliance returns for obligated businesses."],"a":0,"e":"This role concerns sales of resin, pellets or relevant intermediate material, rather than every retail seller of finished consumer goods."},{"id":36,"s":1,"q":"What is meant by end-of-life disposal under the 2026 amendment?","o":["Any storage route, regardless of subsequent processing.","Only refilling containers without changing their structure.","All chemical recovery producing feedstock for new plastic.","Specified recovery routes, excluding stated feedstock recycling."],"a":3,"e":"The definition lists specific recovery and road-use routes and expressly distinguishes the stated feedstock recycling processes."},{"id":37,"s":1,"q":"What is meant by reuse under the 2026 amendment?","o":["Melting an object before manufacturing another item.","Using an object again without structural change.","Converting waste plastic into chemical feedstock material.","Recovering usable energy from discarded plastic packaging."],"a":1,"e":"The object can serve the same or another purpose, provided reuse does not involve changing its structure."},{"id":38,"s":1,"q":"What is meant by plastic waste recycling?","o":["Reprocessing waste, including the amended energy-generation wording.","Collecting waste, regardless of its subsequent treatment.","Storing waste, without undertaking any processing operation.","Transporting waste, without verifying its final destination."],"a":0,"e":"The 2026 general wording also mentions energy generation. Apply the specific EPR requirements when distinguishing recycling and end-of-life streams."},{"id":39,"s":1,"q":"Who is a Plastic Waste Processor?","o":["An entity undertaking recycling or end-of-life disposal.","An entity selling only virgin plastic resin.","An entity providing only waste-collection transport services.","An entity using only plastic-packaged consumer products."],"a":0,"e":"The definition covers both recycling entities and entities performing the specified end-of-life disposal activities."},{"id":40,"s":1,"q":"Who is a Brand Owner under the PWM framework?","o":["A transporter carrying another company's branded packaged goods.","A consumer purchasing products with a registered trademark.","A collector receiving waste bearing another company's brand.","A seller using a registered brand or trademark."],"a":3,"e":"Brand ownership is assessed through the relevant commercial and branding arrangements; merely transporting a branded product does not create this role."},{"id":41,"s":1,"q":"Who is an importer under the PWM Rules?","o":["A domestic transporter of locally manufactured plastic products.","A domestic retailer sourcing goods without import activities.","A commercial importer of covered materials or goods.","An exporter whose activities do not include imports."],"a":2,"e":"The definition extends beyond empty packaging and can include covered goods packed in plastic and relevant plastic raw materials."},{"id":42,"s":1,"q":"Who is a producer under the PWM Rules?","o":["An entity purchasing packaged products for personal consumption.","An entity undertaking the defined covered production activities.","An entity transporting packaging without undertaking covered manufacture.","An entity collecting waste without undertaking covered manufacture."],"a":1,"e":"Review the actual activities, including covered intermediate production and contract manufacture, rather than relying only on the company's chosen job description."},{"id":43,"s":1,"q":"What is plastic packaging?","o":["Plastic machinery used only to manufacture packaging materials.","Product contents measured together with their outer packaging.","Plastic used to protect, store or transport products.","Non-plastic material without any plastic layer or component."],"a":2,"e":"Packaging serves the product during protection, storage or movement; the contents and the packaging are not the same material quantity."},{"id":44,"s":1,"q":"What is plastic waste?","o":["Virgin resin retained as usable raw-material inventory.","Finished packaging retained as unsold usable stock.","Plastic machinery retained for its intended operational use.","Plastic discarded after use or its intended life."],"a":3,"e":"Both consumer discards and relevant production discards can matter; plastic waste is not limited to household litter."},{"id":45,"s":1,"q":"What does EPR stand for?","o":["Extended Producer Responsibility.","Environmental Packaging Registration.","Export Product Regulation.","Extended Processing Revenue."],"a":0,"e":"The abbreviation refers to a responsibility framework, rather than a sales, export or tax-registration programme."},{"id":46,"s":1,"q":"What does PWM stand for?","o":["Packaging Weight Measurement.","Pollution Water Monitoring.","Product Warranty Management.","Plastic Waste Management."],"a":3,"e":"PWM names the plastic-waste regulatory subject; it does not refer to a product warranty or weight-measurement method."},{"id":47,"s":1,"q":"Which Act provides the legal basis for the PWM Rules?","o":["The relevant legislation is the Environment Protection Act 1986.","The relevant legislation is the Companies Act 2013.","The relevant legislation is the Income Tax Act 1961.","The relevant legislation is the Motor Vehicles Act 1988."],"a":0,"e":"The PWM Rules are subordinate environmental legislation made under the Environment Protection Act 1986."},{"id":48,"s":1,"q":"Which ministry notified the Plastic Waste Management Rules?","o":["Ministry of Finance and Department of Revenue.","Ministry of Environment Forest and Climate Change.","Ministry of Commerce and Department of Commerce.","Ministry of Consumer Affairs and Public Distribution."],"a":1,"e":"MoEFCC is the notifying ministry. Pollution control boards perform the functions assigned to them under the framework."},{"id":49,"s":1,"q":"In which year were the original Plastic Waste Management Rules notified?","o":["2010.","2016.","2014.","2022."],"a":1,"e":"The original 2016 rules were subsequently amended; the year of an amendment is not the year of the original notification."},{"id":50,"s":1,"q":"What is the main objective of the Plastic Waste Management Rules?","o":["Universal prohibition of every plastic product and application.","Replacement of environmental duties with voluntary supplier commitments.","Sound waste management with defined stakeholder responsibilities.","Exclusive transfer of packaging responsibilities to end consumers."],"a":2,"e":"The framework combines prevention of harmful handling with management systems and defined stakeholder duties."},{"id":51,"s":2,"q":"Why should packaging categories be reviewed when the packaging material changes?","o":["Brand continuity automatically preserves the previous classification.","Supplier changes always remove the need for classification.","Material changes may alter classification and obligations.","Material changes affect appearance but never compliance classification."],"a":2,"e":"A change from rigid plastic to a flexible laminate, for example, can change both classification and the relevant calculations."},{"id":52,"s":2,"q":"How can incorrect packaging classification affect compliance reporting?","o":["It automatically reduces every applicable reporting obligation.","It affects product prices but never compliance calculations.","It can distort category-wise reporting and targets.","It grants exemption once the return is submitted."],"a":2,"e":"A quantity entered in the wrong category can be assessed against the wrong target even when the total weight is unchanged."},{"id":53,"s":2,"q":"Why should a company verify its packaging category instead of assuming it?","o":["To establish classification from actual packaging construction.","To choose whichever category has the lowest target.","To assume one category covers the entire company.","To replace material specifications with the brand name."],"a":0,"e":"The assessment should use evidence of construction and composition, rather than assumptions based on appearance or product sector."},{"id":54,"s":2,"q":"What is the importance of distinguishing rigid and flexible packaging in EPR reporting?","o":["To report all flexible packaging as multilayered composites.","To apply the relevant category-specific compliance requirements.","To exempt rigid packaging from every EPR obligation.","To merge both formats under one mandatory percentage."],"a":1,"e":"Keeping rigid and flexible quantities separate allows the correct category-specific requirements to be applied."},{"id":55,"s":2,"q":"Why can packaging used for different products require separate classification?","o":["Their material composition and construction can differ.","Their retail prices alone determine their legal categories.","Their product names alone establish separate packaging categories.","Their customers automatically choose the applicable packaging category."],"a":0,"e":"Review each packaging construction; two products from one brand do not necessarily use the same packaging material."},{"id":56,"s":2,"q":"What is the difference between a packaging component and a packaging unit?","o":["A component is the company's entire annual output.","A unit is the resin used before manufacture.","A component is one part of an assembly.","A unit always excludes every detachable packaging part."],"a":2,"e":"A bottle, cap and label can be individual components within the defined packaging unit or assembly."},{"id":57,"s":2,"q":"Why should a business document changes in its packaging design?","o":["Changes can affect weights, categories and claims.","Changes automatically remove every packaging-related reporting requirement.","Design approval replaces the need for material records.","Design changes never affect reported packaging quantities."],"a":0,"e":"The records should show when the design changed and which products or reporting periods used each version."},{"id":58,"s":2,"q":"How can a company identify whether a packaging component contains multiple material layers?","o":["Review layer specifications and supplier material declarations.","Infer the layers only from the printed colour.","Infer the layers only from the retail price.","Assume every pouch contains identical material layers."],"a":0,"e":"Supplier specifications and layer descriptions help establish whether non-plastic material is present in the structure."},{"id":59,"s":2,"q":"Why should packaging data be reconciled with product sales data?","o":["To convert sales revenue directly into plastic tonnes.","To assume all purchases were consumed without adjustments.","To check quantities against sales and stock movements.","To exclude packaging attached to returned products automatically."],"a":2,"e":"Sales, inventory movements, returns and packaging consumption should tell a consistent story about the quantity used."},{"id":60,"s":2,"q":"What is the role of packaging specifications in calculating EPR quantities?","o":["They replace every source record of product sales.","They establish relevant packaging composition and unit weights.","They automatically demonstrate actual processing of packaging waste.","They establish company tax liability instead of quantities."],"a":1,"e":"A documented weight per unit can be combined with relevant quantities and justified adjustments to calculate packaging totals."},{"id":61,"s":2,"q":"Why is it important to distinguish plastic packaging from non-plastic packaging?","o":["To report all packaging material as plastic automatically.","To count non-plastic material as recycled plastic content.","To determine the category using packaging colour alone.","To identify plastic quantities within the applicable scope."],"a":3,"e":"Paper, metal and glass should not automatically be treated as plastic merely because they are part of a packaged product."},{"id":62,"s":2,"q":"What information would help determine the plastic packaging category of a product?","o":["Product selling price, market share and advertising budget.","Material composition, layer structure and packaging format.","Company turnover, office location and employee headcount.","Brand popularity, customer reviews and supplier discount."],"a":1,"e":"Resin names alone may be insufficient; the complete packaging structure and its physical format also matter."},{"id":63,"s":2,"q":"Why should each packaging component be reviewed during an EPR assessment?","o":["The main container automatically determines every component's category.","Components can have different materials and classifications.","Detachable components never require any material assessment.","All secondary components are exempt from quantity reporting."],"a":1,"e":"A cap, sleeve and outer film may require separate material and weight identification even when sold together."},{"id":64,"s":2,"q":"Can the outer packaging of a product be different from its inner packaging?","o":["Yes, their materials and formats can differ.","No, both must always use the same resin.","No, both must always have the same weight.","Yes, but only when both are non-plastic."],"a":0,"e":"An outer film and inner rigid container, for example, can have different constructions and require separate assessment."},{"id":65,"s":2,"q":"What is the difference between packaging made from virgin plastic and packaging containing recycled plastic?","o":["Recycled-content packaging contains no plastic material at all.","Virgin packaging always originates from used consumer containers.","Both descriptions establish identical recycled-material content percentages.","Their resin originates from unrecycled or recovered material."],"a":3,"e":"The distinction concerns the origin of the resin used; it does not mean that recycled-content packaging contains no plastic."},{"id":66,"s":2,"q":"Why should companies maintain category-wise packaging data?","o":["To support category-specific calculations and reporting records.","To apply one chosen percentage to every category.","To avoid measuring the actual plastic packaging quantities.","To remove the need for category-specific target assessment."],"a":0,"e":"A combined total without category separation can hide errors in the application of different requirements."},{"id":67,"s":2,"q":"Why is packaging weight data important for EPR compliance?","o":["Colour alone determines the relevant quantity-based calculations.","Weight determines the relevant quantity-based compliance calculations.","Selling price directly establishes the plastic quantity reported.","Registration alone establishes the annual quantity of packaging."],"a":1,"e":"Reliable weight information converts packaging units into the mass quantities needed for the relevant calculations."},{"id":68,"s":2,"q":"How can a company identify the packaging format used for its product?","o":["Use the product's brand name without inspecting packaging.","Use the company's turnover without reviewing material information.","Assume the format from the supplier's industry sector.","Inspect the packaging and review its technical specifications."],"a":3,"e":"Physical inspection should be supported by specifications where appearance does not reveal the complete material structure."},{"id":69,"s":2,"q":"What is post-consumer plastic packaging waste?","o":["Packaging rejected during manufacture before end-user use.","Packaging discarded after its intended end-user use.","Virgin resin held for a future production batch.","Usable packaging retained within finished-goods stock inventory."],"a":1,"e":"The waste arises after the packaging has served its intended purpose for the final user."},{"id":70,"s":2,"q":"What is pre-consumer plastic packaging waste?","o":["Used packaging discarded after household product consumption.","Used containers collected after customer product consumption.","Usable packaging retained for future manufacturing requirements.","Relevant production waste arising before consumer use."],"a":3,"e":"The waste arises before end-user use, such as relevant production rejects, subject to the precise scope of the definition."},{"id":71,"s":2,"q":"What is the difference between a plastic packaging material and a finished packaged product?","o":["Packaging material always equals the filled product weight.","Packaging surrounds or protects the finished product.","The finished product excludes every outer packaging component.","Packaging material refers only to the product contents."],"a":1,"e":"Do not substitute the filled product's entire weight for the weight of the plastic packaging around it."},{"id":72,"s":2,"q":"Why is the weight of plastic layers relevant when assessing Category III packaging?","o":["The recycled-content basis concerns only non-plastic-layer weight.","The recycled-content basis always includes the product contents.","The recycled-content basis ignores every individual layer weight.","The recycled-content basis concerns the plastic-layer weight."],"a":3,"e":"For the stated recycled-content provision, the non-plastic layers do not form the plastic-layer weight basis."},{"id":73,"s":2,"q":"What does the term “Other” mean in the resin identification note under the 2026 amendment?","o":["Other resins and multi-materials, including specified examples.","Only PET resins used in beverage containers.","Only HDPE resins used in rigid packaging.","Only non-plastic materials used in composite packaging."],"a":0,"e":"Other is an identification grouping for resins and multi-materials outside the separately listed resin types."},{"id":74,"s":2,"q":"Which plastic resin is commonly used in many rigid containers: HDPE or paper?","o":["Paper.","Glass.","HDPE.","Steel."],"a":2,"e":"HDPE is a plastic polymer used in many rigid containers; paper is not a plastic resin."},{"id":75,"s":2,"q":"Which plastic resin is commonly used in beverage bottles: PET or PVC?","o":["PVC.","PS.","PET.","PP."],"a":2,"e":"PET is commonly used for beverage bottles; this does not mean every bottle uses PET."},{"id":76,"s":2,"q":"What is the full form of PS?","o":["The material is polypropylene.","The material is polyvinyl chloride.","The material is polyethylene terephthalate.","The material is polystyrene."],"a":3,"e":"PS identifies polystyrene and should not be confused with PP, which identifies polypropylene."},{"id":77,"s":2,"q":"What is the full form of PP?","o":["The material is polystyrene.","The material is polyvinyl chloride.","The material is polybutylene terephthalate.","The material is polypropylene."],"a":3,"e":"PP identifies polypropylene; a similar abbreviation does not make it the same polymer as PS or PVC."},{"id":78,"s":2,"q":"What is the full form of LDPE?","o":["Linear durable polypropylene elastomer.","Low density polystyrene emulsion.","Layered domestic plastic enclosure.","Low density polyethylene."],"a":3,"e":"LDPE identifies a polyethylene type characterised by low density, commonly encountered in suitable films and flexible products."},{"id":79,"s":2,"q":"What is the full form of PVC?","o":["Polypropylene vinyl compound.","Polyvinyl chloride.","Polyester vinyl carbonate.","Plastic volume coefficient."],"a":1,"e":"PVC identifies polyvinyl chloride, a polymer distinct from polyethylene and polypropylene."},{"id":80,"s":2,"q":"What is the full form of HDPE?","o":["High density polyethylene.","High density polyester.","Heat degraded polypropylene.","High durability plastic."],"a":0,"e":"HDPE identifies high density polyethylene; the abbreviation is a material identifier, not an environmental certification."},{"id":81,"s":2,"q":"What is PET?","o":["Polypropylene ethylene thermoset, a packaging polymer.","Polyethylene terephthalate, a packaging polymer.","Polyvinyl chloride, a packaging polymer.","Polystyrene ethylene thermoplastic, a packaging polymer."],"a":1,"e":"PET identifies polyethylene terephthalate; identifying it does not itself prove recycled content or food-contact compliance."},{"id":82,"s":2,"q":"Can two different packaging formats belonging to different categories have different EPR targets?","o":["Yes, requirements may differ by category and year.","No, every category always shares the same requirements.","No, only the selling price determines EPR targets.","Yes, but only because their printed colours differ."],"a":0,"e":"Compare the actual category-specific provisions for the relevant year rather than assuming all formats share one percentage."},{"id":83,"s":2,"q":"Why should packaging be classified before calculating EPR obligations?","o":["Classification automatically demonstrates completion of waste processing.","Classification identifies the applicable category-specific requirements.","Classification substitutes for every required entity registration.","Classification is required only after filing returns."],"a":1,"e":"Classification is an input to the calculation, so calculating first and classifying afterward risks using the wrong requirement."},{"id":84,"s":2,"q":"What is the significance of identifying the correct packaging category?","o":["It automatically establishes exemption from all EPR targets.","It supports correct requirements, calculations and reporting.","It guarantees approval of every registration application submitted.","It substitutes for evidence of actual packaging quantities."],"a":1,"e":"Correct classification links the material data to the right requirements and supports a defensible return."},{"id":85,"s":2,"q":"Which packaging category was introduced for biodegradable plastic packaging?","o":["Category I.","Category II.","Category V.","Category III."],"a":2,"e":"Category V addresses the specified biodegradable-plastic packaging and commodities, subject to the framework's definitions."},{"id":86,"s":2,"q":"Which packaging category covers compostable plastic packaging under the EPR framework?","o":["Category I.","Category IV.","Category II.","Category V."],"a":1,"e":"Category IV is distinct from Category V; compostable and biodegradable categories should not be merged indiscriminately."},{"id":87,"s":2,"q":"Which packaging category covers multilayered plastic packaging?","o":["Category I.","Category III.","Category IV.","Category V."],"a":1,"e":"The relevant construction includes at least one plastic and one non-plastic layer."},{"id":88,"s":2,"q":"What is the basic difference between Category II and Category III packaging?","o":["Category II is rigid; III includes only flexible plastic.","Category II is flexible; III combines plastic and non-plastic.","Category II is compostable; III includes only biodegradable plastic.","Category II is non-plastic; III includes only rigid plastic."],"a":1,"e":"Multiple plastic layers alone do not make an all-plastic flexible structure Category III."},{"id":89,"s":2,"q":"What is the basic difference between Category I and Category II packaging?","o":["Category I is flexible; Category II is rigid.","Category I is compostable; Category II is biodegradable.","Category I is rigid; Category II is flexible.","Category I is paper; Category II is metal."],"a":2,"e":"The key distinction is the rigid or flexible packaging format, rather than the product brand or printed colour."},{"id":90,"s":2,"q":"Give one example of multilayered plastic packaging.","o":["A bottle made entirely from one PET layer.","A bag made entirely from one polyethylene layer.","A pouch combining plastic and aluminium foil layers.","A container made entirely from one glass layer."],"a":2,"e":"A plastic-and-foil laminate provides both a plastic layer and a non-plastic layer in the same packaging structure."},{"id":91,"s":2,"q":"What is multilayered plastic packaging?","o":["Layered packaging containing only different plastic polymers.","Packaged goods carrying multiple registered brand labels.","Layered packaging containing plastic and non-plastic material.","Packaged goods supplied through several distribution channels."],"a":2,"e":"Review the layer composition; the word multilayer alone does not establish the presence of non-plastic material."},{"id":92,"s":2,"q":"Give one example of flexible plastic packaging.","o":["A plastic drum retaining its rigid shape.","A glass bottle with a rigid body.","A plastic pouch made from flexible film.","A metal can with a rigid body."],"a":2,"e":"A pouch made from flexible plastic film can bend and does not behave like a shape-retaining rigid bottle."},{"id":93,"s":2,"q":"Give one example of rigid plastic packaging.","o":["A polyethylene wrapper made from flexible film.","An HDPE bottle retaining its rigid shape.","A flexible pouch made from polypropylene film.","A flexible sleeve made from stretchable film."],"a":1,"e":"An HDPE bottle can retain its form during ordinary handling and is a typical rigid-packaging example."},{"id":94,"s":2,"q":"What is rigid plastic packaging?","o":["Packaging that substantially retains its physical shape.","Packaging classified solely by its recycled percentage.","Packaging guaranteed to decompose in natural conditions.","Packaging classified solely by its printed colour."],"a":0,"e":"Rigidity describes the format; the presence of recycled content is a separate compositional question."},{"id":95,"s":2,"q":"What type of packaging is included in Category V?","o":["Specified biodegradable plastic packaging, bags and commodities.","Conventional rigid plastic packaging, bottles and jars.","Conventional flexible plastic packaging, films and pouches.","Specified compostable plastic packaging, bags and commodities."],"a":0,"e":"The category covers the specified biodegradable-plastic packaging, carry bags and commodities rather than every item labelled green."},{"id":96,"s":2,"q":"What type of packaging is included in Category IV?","o":["Conventional rigid plastic packaging, bottles and jars.","Specified biodegradable plastic packaging, bags and commodities.","Specified compostable plastic packaging, bags and commodities.","Conventional flexible plastic packaging, films and pouches."],"a":2,"e":"The specified compostable-plastic category must be distinguished from conventional flexible or rigid packaging."},{"id":97,"s":2,"q":"What type of packaging is included in Category III?","o":["Packaging combining plastic and non-plastic material layers.","Packaging containing only conventional rigid plastic material.","Packaging containing only conventional flexible plastic material.","Packaging made exclusively from certified compostable material."],"a":0,"e":"Check for the combination of plastic and non-plastic layers before assigning the material to Category III."},{"id":98,"s":2,"q":"What type of packaging is included in Category II?","o":["Specified rigid packaging retaining its container shape.","Composite packaging combining plastic and non-plastic layers.","Specified packaging made exclusively from biodegradable plastics.","Specified flexible packaging with all-plastic layer structures."],"a":3,"e":"The category includes relevant all-plastic flexible structures, including single and multiple plastic layers."},{"id":99,"s":2,"q":"What type of packaging is included in Category I?","o":["Flexible plastic packaging, including qualifying films.","Rigid plastic packaging, including qualifying containers.","Compostable plastic packaging, including qualifying bags.","Biodegradable plastic packaging, including qualifying commodities."],"a":1,"e":"A rigid plastic bottle or jar is a typical format, subject to the applicable classification of the actual product."},{"id":100,"s":2,"q":"How many plastic packaging categories are covered under the EPR framework in Schedule II?","o":["Two categories, numbered I through II.","Three categories, numbered I through III.","Five categories, numbered I through V.","Seven categories, numbered I through VII."],"a":2,"e":"The amended framework includes Categories I through V; the older four-category structure should not be assumed complete."},{"id":101,"s":3,"q":"What basic information should be collected before preparing an EPR applicability assessment?","o":["Office size, attendance, salaries, furniture and utility bills.","Legal identity, activities, brands, imports and packaging data.","Advertising reach, market share, discounts and customer ratings.","Bank balances, loan limits, dividends and insurance premiums."],"a":1,"e":"An applicability assessment needs facts about the legal entity and its actual material flows before a reliable conclusion can be reached."},{"id":102,"s":3,"q":"What is the importance of identifying all plastic packaging used across a company's products?","o":["To identify every relevant packaging stream for assessment.","To assume the main container covers every component.","To exclude secondary packaging without reviewing its composition.","To treat all product lines as one category."],"a":0,"e":"Looking only at the main container can miss caps, films, labels or other relevant plastic components."},{"id":103,"s":3,"q":"Why should companies periodically review their EPR compliance requirements?","o":["Activities, packaging and applicable requirements can change.","One registration permanently fixes all future compliance duties.","Past compliance automatically establishes future target achievement.","Only new companies need to review amended requirements."],"a":0,"e":"A new product, import activity, packaging design or amendment can change a previously correct assessment."},{"id":104,"s":3,"q":"How can EPR obligations influence a company's packaging procurement decisions?","o":["They require the cheapest option regardless of compliance.","They eliminate the need to verify packaging suppliers.","They influence material choices and supplier specifications.","They prohibit every purchase of new plastic packaging."],"a":2,"e":"Procurement decisions affect the available evidence, material composition and ability to meet relevant packaging obligations."},{"id":105,"s":3,"q":"Why should a business identify the type of processing performed by its waste management partner?","o":["All treatment routes satisfy every target interchangeably.","Collection receipts always establish complete material recycling.","Processing routes can satisfy different compliance requirements.","Every waste contractor performs the same processing activity."],"a":2,"e":"The partner's actual process must be matched with the obligation being claimed, rather than inferred from the name waste manager."},{"id":106,"s":3,"q":"What is the importance of understanding the difference between a recycler and a waste-to-energy operator?","o":["Both activities necessarily produce recycled plastic granules.","Both activities consist solely of temporary waste storage.","Material recovery and energy recovery have distinct outcomes.","Energy recovery always qualifies as unchanged-container reuse."],"a":2,"e":"Recovering polymer material and recovering energy are different outcomes; records and target treatment must reflect the applicable route."},{"id":107,"s":3,"q":"Why should a company verify the registration status of its relevant compliance partners?","o":["To transfer all statutory duties to the partner.","To guarantee unlimited eligibility for every certificate type.","To remove the need for processing-quantity evidence.","To verify current registration and relevant activity scope."],"a":3,"e":"Verify current scope and status, because an old certificate or a general business registration may not cover the service required."},{"id":108,"s":3,"q":"What is the role of a compliance consultant in an EPR assessment?","o":["Assess applicability using verified facts and applicable rules.","Grant statutory registrations without involving the competent authority.","Amend statutory targets according to the client's preferences.","Guarantee approval without examining relevant supporting business records."],"a":0,"e":"A consultant helps interpret evidence and requirements; statutory registration or approval remains with the competent authority."},{"id":109,"s":3,"q":"Why should an EPR-obligated entity maintain documentary evidence of compliance?","o":["To replace the obligation to file prescribed returns.","To prevent authorities from examining the underlying transactions.","To make every unsupported supplier declaration automatically acceptable.","To substantiate reported quantities and compliance claims."],"a":3,"e":"Evidence should connect the claimed result with the entity, period, category and underlying transactions."},{"id":110,"s":3,"q":"What is the purpose of submitting information on a centralised online portal?","o":["To provide prescribed information for regulatory administration.","To obtain automatic exemption from every compliance obligation.","To replace actual processing with an online declaration.","To advertise consumer products instead of reporting compliance."],"a":0,"e":"The submitted information supports administration and verification; entering data does not make an unsupported claim true."},{"id":111,"s":3,"q":"Why must a company substantiate a claimed exemption from recycled-content requirements?","o":["The exemption requires an applicable binding legal basis.","Every company can choose exemption without supporting evidence.","Commercial difficulty automatically creates a valid statutory exemption.","Supplier preference is sufficient for claiming statutory exemption."],"a":0,"e":"Identify the actual binding provision and demonstrate why it applies to the specific packaging application."},{"id":112,"s":3,"q":"What is the importance of understanding exemptions under the EPR framework?","o":["To apply only exemptions whose conditions are met.","To assume every small business has complete exemption.","To replace target calculations with a general declaration.","To extend one exemption to every unrelated duty."],"a":0,"e":"An exemption can be conditional or limited in scope and should not be extended to unrelated duties."},{"id":113,"s":3,"q":"How can a company identify the relevant EPR obligations for its business model?","o":["Use the company's chosen role without checking activities.","Apply identical obligations to every business and product.","Map actual activities against relevant definitions and requirements.","Assume outsourced packaging automatically removes all legal duties."],"a":2,"e":"The same company may manufacture packaging, import products and own brands, so each activity needs review."},{"id":114,"s":3,"q":"Why should EPR calculations distinguish packaging categories?","o":["All categories always require the same percentages.","Categories can have different targets and conditions.","Classification depends exclusively on annual sales revenue.","Category selection is unrelated to compliance calculations."],"a":1,"e":"One combined tonnage does not show whether each category's separate requirement has been met."},{"id":115,"s":3,"q":"What is the difference between recycling obligations and reuse obligations?","o":["Recycling means refilling; reuse means melting discarded packaging.","Recycling means transport; reuse means collecting discarded packaging.","Recycling processes waste; reuse uses qualifying packaging again.","Both obligations concern only purchasing virgin packaging resin."],"a":2,"e":"Repeated use of qualifying packaging is different from processing discarded plastic into material or other eligible outputs."},{"id":116,"s":3,"q":"What is the difference between an EPR target for waste management and a recycled-content target?","o":["Waste management concerns treatment; content concerns material use.","Both concern only collecting and transporting plastic waste.","Both concern only the company's annual sales revenue.","Both are interchangeable once any certificate is purchased."],"a":0,"e":"The two obligations have different subject matter. A certificate relevant to one duty should not be assumed to establish the other."},{"id":117,"s":3,"q":"What is the significance of the recycled plastic content obligation?","o":["It permits manufacture of every otherwise prohibited product.","It automatically demonstrates complete collection of packaging waste.","It promotes recycled-material demand and reduces virgin-material reliance.","It replaces classification of packaging into applicable categories."],"a":2,"e":"Using recovered material in appropriate production creates a market for recycling outputs, subject to applicable safety and legal conditions."},{"id":118,"s":3,"q":"Why should a company reconcile imported packaging quantities with its import records?","o":["To verify the reported imported packaging quantities.","To count the entire imported product as plastic.","To exclude all packaging accompanying imported products automatically.","To replace import quantities with invoice values alone."],"a":0,"e":"The supporting import records should explain the quantities and avoid both omission and counting of unrelated product weight."},{"id":119,"s":3,"q":"What is the role of annual sales data in assessing EPR obligations?","o":["It directly demonstrates processing of every sold package.","It automatically fixes every target at one percent.","It supports estimation of relevant packaging quantities.","It replaces specifications describing the packaging material weight."],"a":2,"e":"Sales data must be combined with packaging specifications and relevant adjustments; revenue alone is not a plastic weight."},{"id":120,"s":3,"q":"Why is EPR registration relevant when evaluating a company's compliance status?","o":["It proves every annual obligation has been fulfilled.","It establishes registration status alongside other compliance evidence.","It permanently eliminates the requirement for annual reporting.","It establishes approval whenever an application remains pending."],"a":1,"e":"Assess registration alongside target fulfilment, returns and supporting records rather than treating registration as complete compliance."},{"id":121,"s":3,"q":"What is the purpose of assessing EPR applicability before approaching a potential client?","o":["To promise complete exemption before reviewing business facts.","To guarantee registration under every available business category.","To avoid collecting information about the client's packaging.","To identify relevant duties before recommending compliance services."],"a":3,"e":"This prevents a proposal from being based on assumptions about a company's role or packaging."},{"id":122,"s":3,"q":"Why should a company distinguish its own-brand products from third-party brands?","o":["Third-party brands are always outside the PWM framework.","Brand arrangements help identify relevant responsible entities.","Own-brand products never create relevant packaging-waste obligations.","Brand ownership alone determines the plastic resin type."],"a":1,"e":"Brand ownership, manufacturing and supply arrangements influence who must assess the relevant duties."},{"id":123,"s":3,"q":"What is the importance of identifying the legal entity responsible for EPR compliance?","o":["One group registration automatically covers every affiliated company.","The correct legal entity must fulfil applicable duties.","A trading name always replaces the incorporated entity.","Only the consultant holds the entity's statutory responsibilities."],"a":1,"e":"A group, brand and incorporated entity are not automatically interchangeable for regulatory records."},{"id":124,"s":3,"q":"Why should a company document the brands under which it sells packaged products?","o":["To replace records of actual packaging manufactured or used.","To connect packaged products with the responsible entity.","To establish automatic exemption for every newly launched brand.","To classify each registered brand as a separate polymer."],"a":1,"e":"Documenting the brands helps connect the products and packaging to the entity responsible for the relevant disclosures."},{"id":125,"s":3,"q":"Can contract manufacturing arrangements affect the identification of an obligated entity?","o":["No, contract manufacturing is excluded from every role assessment.","Yes, actual arrangements can affect the role assessment.","Yes, outsourcing automatically exempts every party from EPR obligations.","No, only the wording of the company name matters."],"a":1,"e":"Outsourcing does not, by itself, settle the legal allocation of roles or eliminate the need for an assessment."},{"id":126,"s":3,"q":"What is the relevance of contract manufacturing to the definition of Producer?","o":["Specified contract manufacturing is included in Producer assessment.","All contract manufacturers are excluded from Producer assessment.","Only overseas contract manufacturers can satisfy the Producer definition.","Only waste transporters can satisfy the Producer definition."],"a":0,"e":"The amended definition expressly brings specified contract-manufacturing arrangements into the role assessment."},{"id":127,"s":3,"q":"Why should a Brand Owner verify the packaging used by its contract manufacturer?","o":["To establish that outsourcing removes every Brand Owner duty.","To replace all packaging evidence with the manufacturing contract.","To verify packaging composition, quantities and compliance data.","To classify every outsourced packaging format as rigid plastic."],"a":2,"e":"The Brand Owner needs reliable data even when another company physically makes or fills the packaging."},{"id":128,"s":3,"q":"What information helps determine whether a company is a Producer or an Importer?","o":["Company logo, advertising theme and preferred brand colours.","Office location, employee attendance and staff travel records.","Product popularity, customer reviews and promotional campaign performance.","Actual manufacturing, intermediate-production and commercial import activities."],"a":3,"e":"Manufacturing records and import documents provide evidence of actual activities rather than a label chosen for convenience."},{"id":129,"s":3,"q":"Why should an Importer maintain details of imported plastic packaging?","o":["To exclude packaging supplied with commercially imported goods.","To substitute retail prices for actual packaging quantities.","To assume all imported material contains recycled plastic.","To support quantity calculations and applicable regulatory reporting."],"a":3,"e":"An Importer's records should identify relevant materials and quantities sufficiently to support its applicable submissions."},{"id":130,"s":3,"q":"What is the role of a brand's product portfolio in an EPR assessment?","o":["It assigns every product to one packaging category.","It automatically removes obligations relating to imported products.","It identifies products and packaging requiring separate review.","It demonstrates recycling without any processor transaction records."],"a":2,"e":"Different products in the portfolio may have different containers, films or laminates and therefore different data requirements."},{"id":131,"s":3,"q":"Why should EPR obligations be calculated using reliable packaging data?","o":["Higher estimates automatically create exemptions from statutory requirements.","Reliable inputs produce defensible calculations and reporting.","Sales revenue can always substitute for packaging weight.","Supplier guesses always replace documented packaging material specifications."],"a":1,"e":"An accurate formula cannot compensate for incorrect weights, omitted packaging or wrong category assignments."},{"id":132,"s":3,"q":"What is the difference between an EPR obligation and an EPR certificate?","o":["A certificate replaces every registration and annual reporting duty.","An obligation is the same as a supplier invoice.","An obligation is a duty; certificates support specified fulfilment.","Both terms refer exclusively to the company's incorporation certificate."],"a":2,"e":"A certificate can support a particular eligible obligation; it is not a blanket cancellation of every responsibility."},{"id":133,"s":3,"q":"What is the purpose of category-wise EPR targets?","o":["To permit unrestricted use of every category's certificates.","To remove the need for measuring packaging quantities.","To assess fulfilment against the relevant packaging category.","To replace submission of the prescribed annual return."],"a":2,"e":"Separate targets allow performance to be assessed against the appropriate category rather than concealed within an overall total."},{"id":134,"s":3,"q":"Why is the quantity of plastic packaging important for EPR compliance?","o":["Packaging quantities provide the basis for relevant calculations.","Packaging colour provides the basis for relevant calculations.","Company profit directly determines the required plastic tonnage.","Quantity matters only when designing consumer advertising campaigns."],"a":0,"e":"The relevant quantity must be established before applying the prescribed percentage or formula."},{"id":135,"s":3,"q":"What is the relationship between plastic packaging placed on the market and EPR obligations?","o":["Each package always creates exactly one tonne of obligation.","Only unsold office furniture determines the relevant packaging obligation.","Packaging quantities never influence the applicable compliance obligation.","Relevant packaging quantities feed the prescribed obligation formula."],"a":3,"e":"The calculation follows the applicable rules, including relevant deductions or adjustments, rather than a universal one-to-one assumption."},{"id":136,"s":3,"q":"Why is the nature of a company's business relevant to EPR applicability?","o":["Company age alone determines every applicable business role.","Employee headcount alone determines the applicable packaging category.","Actual activities determine the applicable defined business roles.","The company's preference overrides the statutory business definitions."],"a":2,"e":"The legal definitions relate to activities such as producing, importing or selling under a brand, not simply the company's age."},{"id":137,"s":3,"q":"Can a business have obligations in more than one role under the PWM framework?","o":["No, each company can perform only one covered activity.","Yes, multiple roles automatically remove every EPR obligation.","No, importing goods legally prevents owning product brands.","Yes, multiple covered activities can create multiple roles."],"a":3,"e":"Assess overlapping roles and the applicable calculation rules to avoid both gaps and unjustified double-counting."},{"id":138,"s":3,"q":"Why should a company review its supply chain when assessing EPR applicability?","o":["To assign every duty automatically to every supplier.","To identify relevant manufacturing, imports and packaging flows.","To exclude imports whenever domestic sales are larger.","To classify packaging solely by the supplier's location."],"a":1,"e":"Supply-chain review identifies who manufactures, imports, brands, supplies and handles the relevant packaging."},{"id":139,"s":3,"q":"How can a company determine whether it qualifies as an Importer under the PWM Rules?","o":["Check only exports without examining any import activities.","Check only ownership of vehicles used for domestic deliveries.","Check commercial imports against the covered Importer definition.","Check only whether products are purchased from local wholesalers."],"a":2,"e":"Commercial imports of covered materials or plastic-packed goods can be relevant even when the company does not manufacture packaging."},{"id":140,"s":3,"q":"What is the difference between a Producer and a Brand Owner?","o":["Producer concerns final consumption; Brand Owner concerns waste transport.","Producer concerns office purchases; Brand Owner concerns resin testing.","Producer and Brand Owner are legally identical in every case.","Producer concerns covered production; Brand Owner concerns branded sales."],"a":3,"e":"The roles describe different activities and can overlap within the same legal entity."},{"id":141,"s":3,"q":"What is the difference between an EPR-obligated entity and a waste collection contractor?","o":["A collection contract automatically cancels the entity's statutory duties.","The entity has duties; the contractor provides collection services.","Every collection contractor automatically becomes the client's Brand Owner.","Both parties always have identical statutory duties and registrations."],"a":1,"e":"Hiring a contractor provides a service arrangement; the entity still needs evidence that its own applicable duties are fulfilled."},{"id":142,"s":3,"q":"Why must a business identify its correct EPR category before applying for registration?","o":["Any category grants identical permission for every business activity.","The cheapest registration fee determines the correct business role.","The role determines the appropriate application and requirements.","The applicant can create a new statutory role independently."],"a":2,"e":"The business role and material category are separate inputs that should both be correctly identified."},{"id":143,"s":3,"q":"What is the role of a Plastic Waste Processor in the EPR system?","o":["To cancel all statutory duties of every client.","To undertake eligible processing and support verified records.","To count temporary storage as completed material recycling.","To authorise manufacture of every prohibited plastic item."],"a":1,"e":"The processor contributes through actual eligible operations and the records required to substantiate them."},{"id":144,"s":3,"q":"Can a company manufacturing plastic packaging have EPR-related obligations?","o":["Yes, assess its Producer role and applicable provisions.","No, plastic-packaging manufacture never creates relevant regulatory duties.","Yes, but registration alone automatically fulfils every annual target.","No, only retail sellers can have EPR-related obligations."],"a":0,"e":"Applicability and any exemptions must be assessed under the relevant provisions; packaging manufacturing is not automatically outside the system."},{"id":145,"s":3,"q":"Is a company importing products packed in plastic potentially covered by the PWM framework?","o":["No, accompanying packaging must always be excluded from assessment.","No, only imports of empty packaging can create duties.","Yes, plastic-packed imports can create relevant Importer duties.","Yes, but only when the imported packaging is glass."],"a":2,"e":"The plastic surrounding an imported product can be relevant even though the product itself is not made of plastic."},{"id":146,"s":3,"q":"What is the responsibility of a Brand Owner under the EPR framework?","o":["Transfer all duties automatically to the final product consumers.","Exclude outsourced packaging from every compliance calculation and report.","Fulfil applicable registration, targets, material-use and reporting duties.","Treat all own-brand packaging as exempt from the framework."],"a":2,"e":"The precise duties depend on the packaging, period and applicable conditions; not every Brand Owner has an identical requirement."},{"id":147,"s":3,"q":"What is the responsibility of an Importer under the EPR framework?","o":["Exclude all packaging accompanying imported finished products from assessment.","Count the entire imported product weight as plastic automatically.","Fulfil applicable duties for covered imported packaging or materials.","Treat foreign invoices as complete substitutes for Indian requirements."],"a":2,"e":"Different imported items and materials may trigger different provisions, so identify the actual import activity first."},{"id":148,"s":3,"q":"What is the responsibility of a Producer under the EPR framework?","o":["Assume that manufacturing packaging creates no relevant statutory obligations.","Substitute a sales invoice for every required environmental registration.","Treat all production scrap as suitable for open burning.","Fulfil applicable duties arising from covered packaging production."],"a":3,"e":"The Producer's duties follow the covered production role and relevant provisions rather than a general assumption of exemption."},{"id":149,"s":3,"q":"Which three types of businesses are commonly identified as Producer, Importer and Brand Owner under EPR?","o":["Producers, Importers and Brand Owners.","Transporters, auditors and final consumers.","Banks, insurers and commercial landlords.","Employees, customers and office visitors."],"a":0,"e":"PIBO is a convenient collective reference to these three roles; the company's actual activities determine which roles apply."},{"id":150,"s":3,"q":"What is the main purpose of EPR for plastic packaging?","o":["Automatic legalisation of every disposable plastic product manufactured.","Accountable management of plastic packaging after its use.","Elimination of all relevant material-recovery and reuse duties.","Replacement of mandatory obligations with voluntary advertising commitments."],"a":1,"e":"The system seeks accountable management of packaging waste rather than relying solely on voluntary collection promises."},{"id":151,"s":4,"q":"What key registration details should be verified before onboarding a Plastic Waste Processor?","o":["Legal identity, validity, facility and registered processing scope.","Company logo, promotional slogan, discounts and sales rankings.","Office furniture, visitor facilities, staff uniforms and brochures.","Website appearance, social followers, customer ratings and testimonials."],"a":0,"e":"Check that the certificate belongs to the actual facility and covers the particular process the company plans to rely on."},{"id":152,"s":4,"q":"Why should a company periodically review the registration status of its processing partners?","o":["A registration remains valid regardless of its conditions.","Registration validity, status and scope can change.","A photocopied certificate proves valid registration permanently.","Only a customer complaint triggers registration-verification duties."],"a":1,"e":"A once-valid partner can later have an expired, suspended or altered registration, so verification should be current."},{"id":153,"s":4,"q":"What is the role of accurate entity identification in regulatory compliance?","o":["It permits interchangeable use of every group-company certificate.","It replaces evidence supporting the reported processing quantities.","It determines the chemical composition of packaging material.","It connects filings to the correct legal entity."],"a":3,"e":"Matching names and identifiers helps avoid using documents that belong to another company or facility."},{"id":154,"s":4,"q":"Why should businesses avoid relying solely on an old registration checklist?","o":["Older checklists always override subsequently notified legal amendments.","Registration requirements cannot change after a company incorporates.","An internal checklist grants the same permission as registration.","Older checklists may omit amended registration requirements."],"a":3,"e":"Old checklists can omit new roles, disclosures or submission requirements introduced after they were prepared."},{"id":155,"s":4,"q":"What is the importance of checking the latest amendment before advising on registration?","o":["The original text always overrides every subsequent amendment.","Advice must reflect the operative amended requirements.","Amendments apply only to newly appointed compliance consultants.","Registration advice can disregard the applicant's actual activities."],"a":1,"e":"Read the operative amended provision and its commencement rather than relying only on a summary."},{"id":156,"s":4,"q":"Why should a compliance consultant distinguish legal requirements from a client's internal procedures?","o":["Internal procedures are distinct from statutory legal duties.","Every internal approval automatically becomes a statutory requirement.","Internal procedures always override notified environmental legal requirements.","Legal duties apply only after internal management approval."],"a":0,"e":"A company may choose additional internal approvals, but those procedures are not automatically statutory requirements."},{"id":157,"s":4,"q":"What should a company do if it cannot determine its correct registration category?","o":["Review the rules and obtain authoritative clarification.","Choose the lowest-fee category without checking actual activities.","Copy another entity's category without reviewing supporting evidence.","Submit conflicting applications and leave both categories unresolved."],"a":0,"e":"Resolve the classification through the rules and reliable clarification; choosing a convenient category can create an incorrect filing."},{"id":158,"s":4,"q":"Why should registration-related correspondence with authorities be archived?","o":["To replace the entity's required registration certificate permanently.","To preserve queries, responses and regulatory decisions.","To avoid responding to subsequent questions from authorities.","To make outdated informal advice override amended legislation."],"a":1,"e":"Correspondence explains the history of authority queries and the responses or conditions that followed."},{"id":159,"s":4,"q":"What is the purpose of retaining proof of a registration submission?","o":["To establish what was submitted and when.","To establish final approval before an application is decided.","To eliminate scrutiny of the submitted supporting documents.","To exempt the applicant from every future regulatory filing."],"a":0,"e":"A submission acknowledgement establishes a filing event; it does not necessarily establish approval of the application."},{"id":160,"s":4,"q":"Why is supporting documentation important during registration?","o":["It substantiates the facts stated in the application.","It permits use of unsupported or invented business information.","It guarantees approval regardless of the applicant's actual activities.","It authorises use of an unrelated company's legal identity."],"a":0,"e":"Documents should support the entity, facility and activities described rather than merely fill an upload slot."},{"id":161,"s":4,"q":"What should a compliance team verify before submitting an online application?","o":["Only website colours and preferred social-media advertising layouts.","Only supplier slogans and informal verbal marketing statements.","Only uploaded filenames without reviewing their actual contents.","Identity, category, required documents and data consistency."],"a":3,"e":"Pre-submission review should check that the application and its attachments tell a consistent and complete story."},{"id":162,"s":4,"q":"Why should a company avoid submitting inconsistent information across regulatory filings?","o":["Inconsistent submissions are automatically treated as approved records.","Inconsistencies undermine accuracy and can trigger queries.","Different names establish stronger evidence of legal identity.","Contradictory figures automatically reduce every applicable statutory target."],"a":1,"e":"Unexplained differences in identity or quantities can undermine the reliability of filings and require correction."},{"id":163,"s":4,"q":"What is the purpose of documenting changes in ownership or business details where relevant?","o":["To create automatic exemption from all existing compliance duties.","To align regulatory records with relevant business changes.","To avoid making any prescribed update to official records.","To substitute ownership details for evidence of actual transactions."],"a":1,"e":"A legal-name or ownership change may need reflected updates in the relevant registrations and supporting records."},{"id":164,"s":4,"q":"Why should a company assess registration requirements separately for each business activity?","o":["The largest revenue activity automatically exempts all other activities.","Only one role may be reviewed for every company.","A single supplier invoice establishes permission for all activities.","Different activities can trigger different registration requirements."],"a":3,"e":"An entity's main activity does not automatically determine all requirements arising from its other activities."},{"id":165,"s":4,"q":"What is the importance of distinguishing mandatory registration from voluntary participation in a programme?","o":["Joining any voluntary programme cancels statutory registration duties.","Optional participation does not replace mandatory registration.","All regulatory registrations are voluntary business preference decisions.","Optional programme membership automatically grants every environmental approval."],"a":1,"e":"Optional engagement in a programme does not replace a registration that is independently required by law."},{"id":166,"s":4,"q":"Why should a business verify the current registration requirements before filing?","o":["To avoid identifying the activity before submitting the application.","To rely exclusively on another company's previously filed application.","To assume identical requirements apply to every registration category.","To use the applicable process and document requirements."],"a":3,"e":"Use the current category-specific requirements rather than copying an old application without review."},{"id":167,"s":4,"q":"What is the purpose of maintaining a registration compliance calendar?","o":["To replace the legal need for valid registrations.","To convert late submissions into automatically timely filings.","To track relevant filings, renewals and updates.","To establish compliance solely through a planned deadline."],"a":2,"e":"A calendar should connect the applicable date, task, responsible person and completion evidence."},{"id":168,"s":4,"q":"Why should a company check for portal notices or regulatory updates?","o":["They can communicate relevant procedural or regulatory changes.","Every notice concerns advertising without any compliance relevance.","Only suppliers may communicate valid regulatory procedural information.","A portal notice automatically repeals every existing statutory requirement."],"a":0,"e":"Notices can identify relevant process changes, filing instructions or required follow-up alongside the legal rules."},{"id":169,"s":4,"q":"What is the importance of acknowledging and tracking regulatory submissions?","o":["To monitor receipt, status and required follow-up.","To treat every acknowledgement as final application approval.","To stop reviewing queries once the application is uploaded.","To delete records after the first submission is acknowledged."],"a":0,"e":"Tracking should continue through queries and final status instead of stopping as soon as an application is uploaded."},{"id":170,"s":4,"q":"Why should a company keep copies of portal submissions?","o":["To avoid retaining any underlying records supporting declared quantities.","To guarantee that every submitted claim is factually correct.","To remove the legal requirement for subsequent periodic reporting.","To preserve the exact information and documents submitted."],"a":3,"e":"A retained submission copy helps establish precisely what was declared and which documents accompanied it."},{"id":171,"s":4,"q":"What is the purpose of regulatory reporting through online portals?","o":["To replace actual processing with an uploaded self-declaration.","To guarantee exemptions for every registered portal user.","To convert estimates automatically into verified processing output.","To provide prescribed information for regulatory oversight."],"a":3,"e":"The online channel supports structured information exchange but does not replace the underlying activity or evidence."},{"id":172,"s":4,"q":"Why may a business need to interact with a state pollution control authority?","o":["For trademark registration covering the company's consumer product brands.","For passport approval covering employees travelling on company business.","For setting market prices of imported plastic resin.","For relevant state-level registration, consents and oversight."],"a":3,"e":"A central portal account does not remove every state-level registration, consent or reporting requirement."},{"id":173,"s":4,"q":"What is the difference between CPCB and an SPCB?","o":["CPCB is municipal; SPCBs perform national legislative functions.","CPCB is private; SPCBs provide commercial banking services.","CPCB regulates states; SPCBs regulate only overseas businesses.","CPCB is central; SPCBs perform state-level functions."],"a":3,"e":"The division is central versus state jurisdiction and assigned functions, rather than two private service providers."},{"id":174,"s":4,"q":"What is the role of SPCBs in monitoring relevant activities within their jurisdictions?","o":["Exclusive notification of all national environmental legal amendments.","Assigned monitoring and enforcement within the state.","Determination of every company's applicable corporate income-tax rate.","Approval of foreign customs clearance for imported goods."],"a":1,"e":"Oversight should be assessed according to the relevant state's jurisdiction and the specific activity involved."},{"id":175,"s":4,"q":"What is the role of CPCB in the centralised EPR system?","o":["Administration of assigned centralised EPR functions.","Direct operation of every local waste-collection service.","Automatic replacement of all applicable state environmental consents.","Automatic compliance approval for every portal account holder."],"a":0,"e":"CPCB's assigned central functions operate alongside, rather than eliminating, the responsibilities of state and local authorities."},{"id":176,"s":4,"q":"Why should the registration category of a vendor match the activity it performs?","o":["Any registration automatically covers every possible processing activity.","Vendor advertising establishes a broader scope than official registration.","One recycling registration automatically permits every industrial treatment route.","Registered scope must cover the activity relied upon."],"a":3,"e":"Registration for one processing activity is not automatically permission or evidence for a different activity."},{"id":177,"s":4,"q":"What is the purpose of maintaining a list of registered compliance partners?","o":["To establish permanent validity without checking subsequent status changes.","To replace every contract and supporting waste receipt.","To support partner verification and ongoing monitoring.","To classify every listed vendor as fully compliant."],"a":2,"e":"A maintained partner list makes it easier to track verified status, scope and relevant changes over time."},{"id":178,"s":4,"q":"Why should a company monitor the validity of registrations relevant to its operations?","o":["Registration validity never changes after its first issue.","Every registration remains valid regardless of its stated expiry.","Invalid registration can undermine operations and compliance claims.","A vendor's ordinary sales invoice automatically renews its registration."],"a":2,"e":"Do not rely on an old copy when its validity or current regulatory status has not been checked."},{"id":179,"s":4,"q":"What should an applicant do if its registration information contains an error?","o":["Ignore the discrepancy until the next customer raises it.","Edit the authority's certificate without using its correction process.","Use another entity's registration number to avoid the discrepancy.","Use the prescribed correction process with supporting evidence."],"a":3,"e":"Corrections should follow the official process so the revised information remains traceable and properly recorded."},{"id":180,"s":4,"q":"Why should a business maintain a record of its registration application?","o":["To track submitted details, queries and decisions.","To substitute the application for every future annual return.","To establish final approval from an unsubmitted draft alone.","To avoid answering authority questions about the actual activities."],"a":0,"e":"The application record supports follow-up and explains the basis on which registration was sought."},{"id":181,"s":4,"q":"What is the significance of a registration number on relevant business records?","o":["It certifies every listed product as suitable for composting.","It identifies the relevant registered entity or activity.","It guarantees the accuracy of every commercial invoice issued.","It substitutes for the actual product's technical material specifications."],"a":1,"e":"A registration number is an identity and verification reference, not a universal product-quality certificate."},{"id":182,"s":4,"q":"Why should registration details be checked before entering into a compliance arrangement?","o":["To treat a verbal promise as sufficient registration evidence.","To avoid checking the activity actually performed by the vendor.","To verify identity, validity and relevant registered scope.","To guarantee every future certificate regardless of underlying processing."],"a":2,"e":"Verification before contracting helps identify a mismatch before the arrangement is used to support a compliance claim."},{"id":183,"s":4,"q":"What is the difference between a registered Plastic Waste Processor and an unverified processor?","o":["Registration is verifiable; unverified status remains unconfirmed.","Unverified status automatically establishes that registration was granted.","Registration establishes unlimited processing output without operational evidence.","A company logo provides the same evidence as registration."],"a":0,"e":"An unverified status is a gap in evidence; do not treat it as proof that registration exists."},{"id":184,"s":4,"q":"Why is it important to match a vendor's legal name with its registration details?","o":["To verify the certificate belongs to the contracting entity.","To allow companies with similar names to share certificates.","To treat every affiliated subsidiary as the same legal entity.","To ignore legal-identity differences when the quoted price is lower."],"a":0,"e":"Similar trade names, group affiliations or logos do not establish that the legal entity on the certificate is the contracting party."},{"id":185,"s":4,"q":"What should a company check before relying on a vendor's registration certificate?","o":["Printing colour, paper thickness, letterhead design and sales discount.","Authenticity, identity, validity, facility and registered activity.","Website ranking, social followers, visitor ratings and market popularity.","Office furnishings, meeting rooms, staff uniforms and promotional gifts."],"a":1,"e":"The relevant activity and facility matter as much as the existence of a certificate bearing a registration number."},{"id":186,"s":4,"q":"Why should a company retain its registration certificate?","o":["It replaces all continuing operational and reporting requirements.","It evidences registration and its relevant conditions.","It proves every current annual target is fulfilled.","It removes evidence requirements for actual waste processing."],"a":1,"e":"Retain the terms and current status as well as the number, because the scope of registration matters."},{"id":187,"s":4,"q":"What is the importance of keeping registration information up to date?","o":["Every registration update automatically cancels the entity's operating rights.","Changes can make previously correct registration information outdated.","Outdated information remains legally preferred once originally submitted.","Accuracy matters only before the first application is uploaded."],"a":1,"e":"Information that was correct when filed can become inaccurate after a business or facility change."},{"id":188,"s":4,"q":"Why should an authorised representative's details be maintained accurately?","o":["To support authorised submissions and reliable regulatory communication.","To allow any employee to submit without valid authorisation.","To replace the company's legal identity with an individual's name.","To remove the need to verify information before filing."],"a":0,"e":"Accurate signatory and contact information supports authorised submissions and reliable regulatory communication."},{"id":189,"s":4,"q":"What is the purpose of the CIN for a company, where applicable?","o":["To certify the company's annual quantity of recycled material.","To identify the resin used in a packaging component.","To replace all required registrations for environmental processing activities.","To identify an incorporated company in corporate records."],"a":3,"e":"The CIN identifies an incorporated company; it does not authorise environmental operations or certify recycling."},{"id":190,"s":4,"q":"What is the relevance of GST information in a business compliance assessment?","o":["It supports tax-identity checks and transaction reconciliation.","It automatically demonstrates fulfilment of every relevant EPR obligation.","It certifies the supplied plastic as biodegradable in water.","It replaces processing records supporting quantities claimed as recycled."],"a":0,"e":"GST details help validate identity and reconcile business records but do not independently establish EPR fulfilment."},{"id":191,"s":4,"q":"Why is the PAN relevant to business registration and compliance records?","o":["It measures the thickness of conventional plastic carry bags.","It certifies packaging performance under industrial composting conditions.","It authorises recycling operations without any other relevant approval.","It supports tax and legal-entity identification checks."],"a":3,"e":"PAN is relevant to tax and entity identification; it is not a packaging-material or processor certificate."},{"id":192,"s":4,"q":"What is the importance of providing accurate business information during registration?","o":["It guarantees registration approval without reviewing any supporting evidence.","It permits invented descriptions where records are temporarily unavailable.","It makes every category-specific supporting document automatically unnecessary.","It supports correct assessment and reliable registration records."],"a":3,"e":"A correct registration assessment depends on truthful and consistent information about the applicant."},{"id":193,"s":4,"q":"Why should an applicant verify the documents required for its registration category?","o":["Every category requires only the applicant's registered company logo.","A competitor's application automatically satisfies the applicant's document requirements.","The selected category never affects the required supporting documents.","Documents depend on the relevant role and activity."],"a":3,"e":"The applicable role determines which documents are needed and whether a particular item is relevant."},{"id":194,"s":4,"q":"What is the difference between registration on the centralised portal and registration with a state authority?","o":["Portal account creation automatically grants every required state approval.","State registrations are never needed after any portal login.","Both automatically replace every applicable Air and Water consent.","The platform and competent authority perform different roles."],"a":3,"e":"Distinguish the electronic filing platform from the competent authority and the separate statutory approvals involved."},{"id":195,"s":4,"q":"Why should an entity identify the correct registration category before applying?","o":["To match the application to actual business activities.","To choose whichever category has the shortest application form.","To establish that every other business activity is exempt.","To avoid disclosing the applicant's actual manufacturing or imports."],"a":0,"e":"A registration should describe what the entity actually does rather than a category selected to reduce paperwork."},{"id":196,"s":4,"q":"What is the role of a Pollution Control Committee in the registration framework?","o":["Issue of company PAN numbers for all commercial businesses.","Exclusive national notification of statutory packaging-category target percentages.","Assigned registration and oversight in the Union territory.","Automatic replacement of every municipal waste-management enforcement function."],"a":2,"e":"A PCC carries out the assigned functions for the relevant Union territory under the applicable framework."},{"id":197,"s":4,"q":"What is the role of a State Pollution Control Board in the registration of plastic raw material manufacturers and importers?","o":["Handle prescribed registrations for covered raw-material entities.","Register every product brand under national trademark legislation.","Certify all plastic packages for unrestricted food-contact use.","Set selling prices for every domestic virgin-resin transaction."],"a":0,"e":"The 2024 provision assigns the relevant application route to the SPCB or concerned PCC for plastic raw material activities."},{"id":198,"s":4,"q":"Which types of entities are covered by the registration provisions under the 2024 amendments?","o":["Only final consumers purchasing goods for personal household use.","Only manufacturers producing paper without any plastic-related business activity.","Only companies selling products outside every Indian commercial market.","Covered entities according to their applicable registration provisions."],"a":3,"e":"Coverage must be assessed role by role; being listed in a broad group does not mean every entity has identical requirements."},{"id":199,"s":4,"q":"What is the purpose of registration under the centralised PWM portal?","o":["To record covered entities and administer relevant compliance.","To approve every plastic product without checking independent restrictions.","To remove every reporting duty once the account exists.","To replace operative legislation with the company's internal declarations."],"a":0,"e":"Registration creates a verifiable entry for the covered entity and supports the administration of its relevant obligations."},{"id":200,"s":4,"q":"Which authority developed the centralised online portal for relevant PWM registrations?","o":["Central Pollution Control Board.","Reserve Bank of India.","Election Commission of India.","Ministry of Corporate Affairs."],"a":0,"e":"CPCB develops the relevant centralised system; this does not make every other authority's functions unnecessary."},{"id":201,"s":5,"q":"Why should a company regularly review its product range against the current prohibited-item requirements?","o":["To assume every previously sold product remains permitted.","To classify every plastic product as automatically banned.","To replace product assessment with environmental marketing claims.","To detect products affected by current prohibitions."],"a":3,"e":"Product lines can change, and a permitted packaging format should not be confused with a specifically prohibited item."},{"id":202,"s":5,"q":"What is the role of inspection and enforcement in preventing the circulation of prohibited plastic items?","o":["To legalise prohibited items after their first sale.","To detect violations and enforce relevant prohibitions.","To replace every applicable technical product specification.","To permit unrestricted stocking before a complaint occurs."],"a":1,"e":"Inspection establishes whether products and activities meet the rules and provides a basis for action where violations are found."},{"id":203,"s":5,"q":"Why should compliance advice distinguish central rules from any applicable additional state or local restrictions?","o":["Central rules automatically remove every additional local restriction.","Local rules always replace every central statutory requirement.","Businesses can choose whichever jurisdiction's requirements they prefer.","Additional state or local restrictions may also apply."],"a":3,"e":"A complete assessment checks all applicable layers of requirements instead of assuming one source removes the others."},{"id":204,"s":5,"q":"What is the importance of checking the applicable rules before launching an alternative plastic product?","o":["Alternatives must independently meet the applicable requirements.","Alternative branding automatically establishes complete legal product compliance.","Every biodegradable claim creates an unrestricted statutory exemption.","Product colour alone establishes the applicable regulatory classification."],"a":0,"e":"A new material description or environmental claim does not itself establish that the product is legally permitted."},{"id":205,"s":5,"q":"Why should a manufacturer retain test reports for regulated plastic products where required?","o":["To substantiate conformity with applicable technical requirements.","To replace every registration relevant to manufacturing activities.","To make a failed batch automatically satisfy specifications.","To avoid identifying the actual product being supplied."],"a":0,"e":"The report should identify the actual product or material tested and support the specification being claimed."},{"id":206,"s":5,"q":"What evidence can help a company demonstrate compliance with carry bag specifications?","o":["A green label without supporting material specifications.","A discounted invoice without supporting technical measurements.","Matched specifications, measurements and supporting test evidence.","A supplier slogan without supporting conformity evidence."],"a":2,"e":"The evidence should match the actual bag type and the production or supply being assessed."},{"id":207,"s":5,"q":"Why should a business not assume that labelling a plastic item “eco-friendly” makes it compliant?","o":["An eco-friendly claim automatically cancels all product restrictions.","An environmental slogan replaces every required technical test.","Marketing terms do not establish statutory conformity.","A green logo establishes certification without supporting documents."],"a":2,"e":"A marketing term cannot substitute for mandatory specifications, certification or other applicable conditions."},{"id":208,"s":5,"q":"What is the difference between biodegradable plastic and an item that is legally exempt from a specific prohibition?","o":["Biodegradable materials automatically qualify for every product exemption.","Exemption removes every technical requirement for the material.","Disposable products automatically satisfy the biodegradable-plastic material definition.","Material performance and legal exemption are distinct questions."],"a":3,"e":"Whether a product is exempt depends on the relevant legal conditions, not simply a statement that the material biodegrades."},{"id":209,"s":5,"q":"Why should a business verify both the material and the specifications of a carry bag?","o":["Colour and branding establish every relevant carry-bag requirement.","Material and physical specifications determine relevant requirements.","A compliant resin automatically guarantees a compliant finished bag.","All bag types require only a thickness measurement."],"a":1,"e":"Check the applicable standard for that particular bag type rather than treating every carry bag as physically identical."},{"id":210,"s":5,"q":"What should a retailer do if a supplier offers carry bags that fail the applicable thickness requirement?","o":["Distribute the bags until an official inspection occurs.","Print a green label and distribute the bags.","Accept the bags because discounted goods are exempt.","Withhold distribution and resolve the specification failure."],"a":3,"e":"A below-specification bag should not be distributed on the assumption that the supplier's invoice makes it acceptable."},{"id":211,"s":5,"q":"Why is public awareness relevant to the implementation of plastic restrictions?","o":["It removes every manufacturer's responsibility for prohibited products.","It supports understanding and adoption of lawful practices.","It substitutes completely for all local regulatory enforcement.","It makes a prohibited item lawful after purchase."],"a":1,"e":"People must know which practices and products are restricted for implementation to work effectively in day-to-day use."},{"id":212,"s":5,"q":"What is the role of local bodies in enforcing restrictions on plastic waste generated by waste generators?","o":["Grant blanket exemption from all relevant packaging requirements.","Rewrite national definitions according to local supplier preferences.","Assess customs duty on commercially imported plastic materials.","Enforce assigned local waste-generator and product-restriction provisions."],"a":3,"e":"The enforcement function concerns the provisions assigned to the local body within its jurisdiction."},{"id":213,"s":5,"q":"Why should businesses maintain purchase records for plastic raw materials?","o":["To substitute purchase values for plastic weights automatically.","To remove every applicable restriction on raw-material supply.","To establish material sources, quantities and transaction traceability.","To authorise manufacture of every prohibited plastic item."],"a":2,"e":"Purchase records help establish what was supplied, in what quantity and by which supplier."},{"id":214,"s":5,"q":"What is the importance of checking whether a plastic product falls within a specified prohibition?","o":["Every disposable item is automatically prohibited without qualification.","Every recyclable material is automatically exempt from prohibitions.","The supplier's product description alone establishes legal permission.","Specific item descriptions determine whether prohibition applies."],"a":3,"e":"Read the notified item description and conditions instead of deciding legality from the word disposable alone."},{"id":215,"s":5,"q":"Why should a supplier understand the intended use of plastic raw material?","o":["Intended use automatically transfers every duty to consumers.","Buyer registration never matters if the order is profitable.","Intended use can affect whether supply is permitted.","Supplier awareness automatically grants permission for prohibited manufacture."],"a":2,"e":"A buyer's intended activity can be relevant to whether supplying the material is permitted."},{"id":216,"s":5,"q":"What is the difference between a raw material supplier and a manufacturer of finished plastic goods?","o":["Suppliers always manufacture every finished item their customers sell.","Manufacturers never purchase or use any plastic raw materials.","Both roles describe only the transportation of discarded waste.","Suppliers sell inputs; manufacturers convert them into goods."],"a":3,"e":"One role supplies input material, while the other makes the finished article; a business can perform both roles."},{"id":217,"s":5,"q":"Why should suppliers verify a buyer's registration before selling plastic raw material?","o":["To guarantee every buyer's future fulfilment of all obligations.","To meet applicable buyer-registration and raw-material supply restrictions.","To replace checks on the material's intended downstream use.","To authorise supplies to units manufacturing any prohibited items."],"a":1,"e":"Check the registration relevant to the covered transaction instead of relying on a general assurance that the buyer is a business."},{"id":218,"s":5,"q":"What is the purpose of preventing plastic raw material from being supplied to prohibited-item manufacturers?","o":["To exempt registered suppliers from monitoring any downstream use.","To legalise prohibited products once materials are properly invoiced.","To prevent supply chains from enabling prohibited manufacture.","To replace all material traceability with a general declaration."],"a":2,"e":"Restricting supply helps prevent the prohibited activity before the finished product reaches the market."},{"id":219,"s":5,"q":"Why should raw material invoices identify the registered buyer where required?","o":["To replace every applicable annual transaction-reporting requirement permanently.","To certify every finished product manufactured by the buyer.","To remove all duties applying to raw-material suppliers.","To connect transactions with the verified registered buyer."],"a":3,"e":"A buyer's registration reference helps link the invoice to the verified legal entity involved in the sale."},{"id":220,"s":5,"q":"What warning is required on relevant plastic raw material packaging under the applicable provisions?","o":["A declaration permitting all products made from the material.","A statement certifying every resin as industrially compostable.","A declaration that buyers never require any relevant registration.","A warning against prohibited and specified substandard uses."],"a":3,"e":"The prescribed warning addresses prohibited uses, including specified substandard sheets and bags, rather than promising universal material safety."},{"id":221,"s":5,"q":"Why do the rules require relevant plastic raw material suppliers to observe restrictions on sales to units manufacturing prohibited items?","o":["To accelerate production once the buyer places an order.","To exempt material sellers from all transaction-recordkeeping requirements.","To make the buyer's identity irrelevant for every transaction.","To prevent raw-material supplies supporting prohibited manufacturing activities."],"a":3,"e":"The supply restriction supports enforcement upstream of the manufacture and distribution of prohibited goods."},{"id":222,"s":5,"q":"What is the relevance of the prohibition on manufacturing certain single-use plastic items to raw material sellers?","o":["Raw-material sellers are excluded from all product-related restrictions.","Relevant supply restrictions can also affect material sellers.","Cash transactions automatically override otherwise applicable supply prohibitions.","Registration permits buyers to manufacture every prohibited plastic item."],"a":1,"e":"A supplier should not assume that selling raw material is unrelated to a prohibition on its specified downstream use."},{"id":223,"s":5,"q":"Why should a compliance officer maintain evidence of a carry bag's thickness?","o":["To demonstrate conformity with the applicable minimum thickness.","To establish that every supplied bag is biologically degradable.","To replace the records identifying the bag supplier permanently.","To avoid examining the specification of actual supplied bags."],"a":0,"e":"Measured or documented thickness provides evidence that can be compared with the applicable minimum."},{"id":224,"s":5,"q":"What is the purpose of monitoring compliance with carry bag thickness requirements?","o":["To detect bags failing the applicable minimum specification.","To remove every restriction on the sale of bags.","To replace the need to identify the bag material.","To permit thinner bags whenever procurement costs increase significantly."],"a":0,"e":"Checking actual production and supply helps identify bags that fail the relevant physical requirement."},{"id":225,"s":5,"q":"Why should a company review its inventory when a plastic product is found to be prohibited?","o":["To sell affected stock before an inspection takes place.","To make existing stock exempt by relabelling it reusable.","To identify affected stock and prevent unlawful distribution.","To assume all previously purchased stock remains automatically permitted."],"a":2,"e":"The inventory review should identify affected goods and determine the lawful handling of the stock."},{"id":226,"s":5,"q":"What is the importance of communicating applicable plastic restrictions to suppliers?","o":["To make supplier emails substitute for notified legal requirements.","To align supplies with the applicable product restrictions.","To transfer every statutory duty to the supplier automatically.","To remove any need to examine the products supplied."],"a":1,"e":"Clear specifications help prevent ordering or receiving goods that fail applicable restrictions."},{"id":227,"s":5,"q":"Why should a seller avoid supplying prohibited single-use plastic items?","o":["Customer demand automatically permits otherwise prohibited commercial supply.","Supply may breach applicable prohibitions and trigger enforcement.","Only manufacturers can be affected by item prohibitions.","Bulk purchasing automatically exempts otherwise prohibited plastic items."],"a":1,"e":"A buyer's request or willingness to pay does not override a legal prohibition on supply."},{"id":228,"s":5,"q":"What should a manufacturer verify before introducing a new plastic product into the market?","o":["Applicable restrictions, specifications, labels and required approvals.","Expected profit, sales commissions and promotional campaign discounts.","Competitor prices, advertising budgets and retail shelf position.","Product popularity, customer rankings and social-media engagement levels."],"a":0,"e":"Assess the actual item and its intended use before manufacture or market launch rather than relying on competitor practice."},{"id":229,"s":5,"q":"Why should a business not assume that every disposable plastic product is automatically prohibited?","o":["Only specified items and conditions establish the prohibition.","All disposable plastic products have identical legal prohibition status.","Recyclability automatically exempts every disposable product from restrictions.","A supplier's disposable label creates the statutory prohibition itself."],"a":0,"e":"The central prohibition identifies particular products and conditions; other requirements may still apply to items outside that list."},{"id":230,"s":5,"q":"What is the purpose of restrictions on specified plastic cutlery and disposable items?","o":["To reduce harm from identified problematic disposable items.","To prohibit every plastic packaging format without any exception.","To remove the requirement for segregation of plastic waste.","To permit open burning of any collected plastic material."],"a":0,"e":"The restriction responds to the environmental problems associated with the specified short-lived products."},{"id":231,"s":5,"q":"Why should procurement teams verify the compliance of plastic products purchased from suppliers?","o":["To treat tax invoices as complete product conformity evidence.","To avoid procuring products that fail applicable requirements.","To replace every measurement with an environmental marketing claim.","To permit otherwise prohibited products when purchased in bulk."],"a":1,"e":"A purchase invoice establishes a transaction, but it does not by itself prove the product meets technical or legal requirements."},{"id":232,"s":5,"q":"What is the importance of checking the current list of prohibited single-use plastic items?","o":["The current list identifies the specified prohibited items.","All plastic items are prohibited regardless of notified descriptions.","A supplier may freely revise the notified prohibition list.","An old brochure overrides any subsequently amended statutory provision."],"a":0,"e":"Check the exact item and the operative provision, including relevant conditions and applicable additional restrictions."},{"id":233,"s":5,"q":"Why should businesses maintain product specifications for plastic items they manufacture?","o":["To support assessment of composition and physical conformity.","To replace every required test without assessing technical evidence.","To remove the need to record production-design changes.","To classify all manufactured products by printed colour alone."],"a":0,"e":"Specifications connect the product being manufactured with the material and dimensional requirements used for assessment."},{"id":234,"s":5,"q":"What is the relevance of Rule 4 in the PWM Rules?","o":["It prescribes relevant product conditions and restrictions.","It deals exclusively with company corporate tax liability.","It permits unrestricted burning of discarded plastic material.","It exempts every packaging format from regulatory requirements."],"a":0,"e":"Rule 4 is central to checking the conditions and restrictions that apply to the relevant plastic item."},{"id":235,"s":5,"q":"Why should businesses distinguish prohibited products from permitted plastic packaging?","o":["Purchasing EPR certificates legalises every otherwise prohibited plastic item.","Every packaging format is independently prohibited by the rules.","Permitted packaging never creates any relevant compliance responsibilities.","Product permission and packaging-waste duties require separate assessment."],"a":3,"e":"Fulfilling packaging-waste obligations does not, by itself, legalise a product that is independently prohibited."},{"id":236,"s":5,"q":"What is the difference between a restriction on an item and an EPR obligation for packaging?","o":["Restrictions measure recycled content; EPR sets product selling prices.","Restrictions apply only to consumers; EPR exempts all manufacturers.","Restrictions and EPR describe identical voluntary environmental advertising claims.","Restrictions govern product permission; EPR governs relevant waste duties."],"a":3,"e":"Permission to market an item and responsibility for its packaging waste are separate regulatory questions."},{"id":237,"s":5,"q":"Why is checking GSM relevant for non-woven carry bags?","o":["GSM is the conventional bag's thickness measured in microns.","GSM directly identifies the legally responsible registered Brand Owner.","GSM establishes that the material contains no plastic polymer.","GSM is the relevant non-woven mass-per-area measure."],"a":3,"e":"GSM is mass per unit area, so it must not be confused with a thickness measurement expressed in microns."},{"id":238,"s":5,"q":"What is the significance of measuring the thickness of a plastic carry bag?","o":["To certify that every bag can undergo composting.","To compare thickness against the applicable minimum.","To substitute thickness for all material declarations required.","To establish the processor's annual recycled-material output quantity."],"a":1,"e":"The thickness reading should be assessed against the applicable requirement for the relevant carry-bag material."},{"id":239,"s":5,"q":"Why should manufacturers verify the specifications of carry bags before production?","o":["To remove all need for subsequent production-quality checks.","To assume any resin automatically creates a compliant bag.","To prevent production of bags with incorrect specifications.","To make the finished bag's physical dimensions legally irrelevant."],"a":2,"e":"Checking before production reduces the risk of manufacturing an entire batch with the wrong specification."},{"id":240,"s":5,"q":"Why should retailers check the compliance of plastic carry bags they distribute?","o":["Retailers may distribute any bag if supplied without charge.","A supplier invoice overrides every carry-bag physical requirement.","Compliance applies only after a retailer receives an inspection.","Distribution must meet applicable bag restrictions and specifications."],"a":3,"e":"The retailer should assess the bags actually supplied rather than assume responsibility ends with the manufacturer."},{"id":241,"s":5,"q":"What is the role of local authorities in enforcing applicable restrictions on plastic waste?","o":["Exclusive issue of every nationally applicable technical standard.","Determination of all customs duties on imported materials.","Enforcement of assigned provisions within their jurisdiction.","Universal exemption from restrictions through informal verbal permission."],"a":2,"e":"The authority's powers depend on the relevant provisions and jurisdiction, not a general permission to waive restrictions."},{"id":242,"s":5,"q":"What is the role of local bodies in enforcing specified restrictions on plastic carry bags?","o":["Exempt every retail outlet from all bag specifications.","Set national tax rates for carry-bag manufacturing companies.","Approve every thinner bag once a supplier requests it.","Monitor and enforce assigned local carry-bag restrictions."],"a":3,"e":"Carry-bag enforcement can include checking specified restrictions and taking action within the local body's assigned powers."},{"id":243,"s":5,"q":"Why must businesses verify whether a plastic item is prohibited before manufacturing or selling it?","o":["To accelerate sales before authorities identify the affected products.","To avoid activities prohibited by the applicable provisions.","To treat every buyer request as an official exemption.","To replace conformity checks with a generic invoice disclaimer."],"a":1,"e":"Commercial demand and competitor sales do not establish that an item is legally permitted."},{"id":244,"s":5,"q":"What is the difference between a plastic carry bag and plastic packaging that forms an integral part of a sealed product?","o":["Integral sealed-product packaging is excluded from the carry-bag definition.","Every sealed-product wrapper automatically becomes a plastic carry bag.","Both formats always have identical definitions and physical requirements.","Plastic carry bags must contain only uncoated paper material."],"a":0,"e":"The distinction depends on the purpose and construction of the packaging, including the integral sealed-product exclusion."},{"id":245,"s":5,"q":"What minimum GSM requirement applies to non-woven plastic carry bags under the applicable provisions?","o":["20 GSM.","40 GSM.","60 GSM.","100 GSM."],"a":2,"e":"The stated minimum is a mass-per-area specification for the relevant non-woven bags, not a universal thickness specification."},{"id":246,"s":5,"q":"What does GSM mean in relation to non-woven carry bags?","o":["Grams per single micron.","Gross sales margin measure.","Grams per square metre.","General segregation method measure."],"a":2,"e":"A 60 GSM specification refers to 60 grams per square metre of material, not 60 microns of thickness."},{"id":247,"s":5,"q":"From which date did the 120-micron minimum thickness requirement for plastic carry bags take effect?","o":["1 January 2020.","1 July 2021.","31 December 2022.","31 March 2026."],"a":2,"e":"This is the commencement date for the stated 120-micron requirement, rather than the date of the original PWM Rules."},{"id":248,"s":5,"q":"What minimum thickness is prescribed for plastic carry bags under the applicable PWM provisions?","o":["20 microns.","50 microns.","120 microns.","75 microns."],"a":2,"e":"Apply the 120-micron rule to the covered conventional bags and check the specific exceptions or separate requirements."},{"id":249,"s":5,"q":"What is the main objective of restricting specified single-use plastic items?","o":["To prohibit every application of all plastic material universally.","To remove responsibilities for collection of discarded plastic waste.","To permit uncontrolled disposal of every collected plastic item.","To reduce harm from specified single-use plastic items."],"a":3,"e":"The restriction targets specified items; it should not be described as an indiscriminate ban on every plastic application."},{"id":250,"s":5,"q":"What is meant by a prohibited single-use plastic item?","o":["Every item intended for disposal after a single use.","Every product manufactured using any recovered recycled plastic material.","Only plastic waste discarded by households after consumer use.","An item covered by a specific legal prohibition."],"a":3,"e":"The legal list and operative conditions establish prohibition; intended single use alone does not settle the question."},{"id":251,"s":6,"q":"Why should the marking and labelling requirements be reviewed when the applicable rules are amended?","o":["Approved artwork never requires review after its original approval.","Amendments can change required information or disclosure mechanisms.","Every amendment automatically removes all applicable packaging-labelling requirements.","Supplier preferences always override every statutory packaging-information requirement."],"a":1,"e":"An earlier approved label may need revision if the required information or permitted method of providing it changes."},{"id":252,"s":6,"q":"What should a manufacturer verify before printing a biodegradable-plastic claim?","o":["Only supplier reputation, brand recognition and customer satisfaction ratings.","Only product colour, surface finish and outer artwork design.","Relevant certification, testing, degradation period and receiving environment.","Only material price, purchase quantity and agreed delivery timeline."],"a":2,"e":"The claimed breakdown must be supported for the stated period and receiving environment under the applicable process."},{"id":253,"s":6,"q":"Why should a business avoid using the term “compostable” without the required supporting compliance?","o":["The printed claim automatically grants the required product approval.","The claim requires applicable standards and compliance evidence.","Plant-based content automatically establishes every necessary compostability certification.","Recycled content alone establishes compliance with compostability requirements."],"a":1,"e":"The term describes a performance claim that needs evidence, rather than a design choice that can be printed without support."},{"id":254,"s":6,"q":"What is the importance of retaining evidence supporting recycled-content percentages?","o":["To redefine virgin plastic as recycled through internal declarations.","To substantiate the percentage claimed in relevant records.","To replace every record of the packaging material supplied.","To eliminate all checks on the supplier's material quantities."],"a":1,"e":"The claimed percentage should be linked to identifiable materials, transactions and relevant production records."},{"id":255,"s":6,"q":"Why should a company periodically review the accuracy of its packaging information?","o":["Approved packaging information remains accurate regardless of subsequent changes.","Only the first production batch requires accurate packaging information.","Material, identity or legal changes can affect accuracy.","Label accuracy concerns advertising rather than applicable compliance requirements."],"a":2,"e":"Supplier changes, new resin, altered content or updated registrations can make previously correct information outdated."},{"id":256,"s":6,"q":"What is the role of a barcode or QR code in improving packaging traceability?","o":["It links packaging with relevant product-information records.","It automatically certifies the physical recycling of that package.","It grants unrestricted exemption from all packaging-information requirements.","It establishes compostability without any relevant material-testing evidence."],"a":0,"e":"The code must link to meaningful and reliable information; printing a code by itself does not substantiate the package's properties."},{"id":257,"s":6,"q":"Why should packaging suppliers provide accurate material declarations?","o":["Declarations automatically permit unsupported environmental claims on every product.","A brand logo substitutes for all packaging composition information.","Accurate declarations support classification, claims and quantity calculations.","Incorrect declarations cannot affect any relevant EPR compliance calculation."],"a":2,"e":"The recipient needs to know the actual composition, not simply the supplier's preferred environmental description."},{"id":258,"s":6,"q":"What is the importance of ensuring consistency between a product label and its technical documentation?","o":["To allow preferred marketing claims regardless of technical evidence.","To substitute approved artwork for required material-testing records.","To treat contradictory product information as automatically legally acceptable.","To ensure the claims match actual product evidence."],"a":3,"e":"If the label and technical evidence disagree, the claim should be investigated before the packaging is produced or supplied."},{"id":259,"s":6,"q":"Why should a business check whether recycled plastic is permitted for its intended application?","o":["Some applications restrict recycled material or impose conditions.","All applications permit every recycled plastic without further checks.","Food-contact applications never impose additional material-use requirements.","Packaging colour determines whether recycled resin is legally permitted."],"a":0,"e":"Permission depends on the intended application and applicable legal or safety restrictions, not simply the fact that the resin is recycled."},{"id":260,"s":6,"q":"Why is compliance with food-contact requirements important for recycled plastic packaging?","o":["Every recycled polymer automatically qualifies for food-contact applications.","A recycling symbol replaces all relevant food-safety requirements.","Applicable food-safety requirements remain relevant to packaging.","Non-food certification automatically permits unrestricted food-contact material use."],"a":2,"e":"Material recovery does not automatically establish suitability for contact with food; the applicable food-safety requirements remain relevant."},{"id":261,"s":6,"q":"Which organisation is assigned the role of specifying separate colour or marking requirements under the 2024 amendment?","o":["Central Pollution Control Board.","Food Safety Standards Authority.","Bureau of Indian Standards.","Central Drugs Standard Organisation."],"a":2,"e":"BIS is the standards body assigned this role; it should not be confused with CPCB's separate functions."},{"id":262,"s":6,"q":"What is the purpose of a separate colour or marking requirement for specified compostable or biodegradable products?","o":["To exempt labelled products from all applicable regulatory requirements.","To guarantee immediate breakdown in every natural receiving environment.","To distinguish specified materials for identification and handling.","To replace every applicable material test with a colour."],"a":2,"e":"Distinct identification supports appropriate recognition and handling of the specified material types."},{"id":263,"s":6,"q":"Why should a business retain supporting documents for a compostable-plastic claim?","o":["To remove any need to identify the material tested.","To make conventional plastic compostable through a supplier declaration.","To demonstrate conformity of the actual compostability claim.","To eliminate all relevant certification requirements before product sale."],"a":2,"e":"Retained evidence allows the business to substantiate the exact product and claim during a query or audit."},{"id":264,"s":6,"q":"What is the role of testing standards in establishing whether a plastic material meets applicable requirements?","o":["They automatically approve materials without carrying out prescribed testing.","They define methods and criteria for conformity assessment.","They replace the need to identify the tested material.","They apply only to the artwork used in advertisements."],"a":1,"e":"Testing standards define how conformity is evaluated under specified conditions rather than allowing claims based on appearance."},{"id":265,"s":6,"q":"Why should a company verify evidence before making an environmental claim on packaging?","o":["To guarantee sales regardless of the claim's factual accuracy.","To substantiate claims and avoid misleading packaging information.","To convert any environmental slogan into official material certification.","To remove all business responsibility for printed product claims."],"a":1,"e":"An environmental claim should describe a property the business can actually demonstrate for the material supplied."},{"id":266,"s":6,"q":"What is the difference between a compostability claim and a biodegradability claim?","o":["Both guarantee immediate material breakdown in every natural environment.","Compostability and biodegradability require different specified conditions.","Compostability describes only the potential for future material recycling.","Biodegradability establishes only the percentage of recycled material used."],"a":1,"e":"The receiving conditions and applicable standards matter, so neither claim should be interpreted as immediate breakdown in all environments."},{"id":267,"s":6,"q":"Why should a business distinguish a recycled-content claim from a recyclability claim?","o":["Both terms establish that packaging contains entirely recycled material.","Recyclability automatically proves actual incorporation of recovered material.","Content describes material used; recyclability describes processing potential.","Recycled content guarantees access to recycling in every location."],"a":2,"e":"A package may be recyclable without containing recycled material, and a recycled-content claim does not prove universal recyclability."},{"id":268,"s":6,"q":"Why is correct identification of a plastic resin important for recycling?","o":["All polymers can always be processed identically without separation.","Polymer differences affect sorting and suitable processing conditions.","Resin identification determines only the packaging's printed label colour.","A resin code automatically replaces every waste-segregation requirement."],"a":1,"e":"Incompatible polymers can affect separation and output quality, so material identification has practical processing value."},{"id":269,"s":6,"q":"What does PS stand for in plastic identification?","o":["The material is polypropylene.","The material is polystyrene.","The material is polyethylene terephthalate.","The material is polyvinyl chloride."],"a":1,"e":"PS is the identifier for polystyrene; it is a different polymer abbreviation from PP or PET."},{"id":270,"s":6,"q":"What does PP stand for in plastic identification?","o":["Polypropylene.","Polystyrene.","Polycarbonate.","Polyvinyl chloride."],"a":0,"e":"PP is the identifier for polypropylene; the abbreviation does not itself certify any environmental property."},{"id":271,"s":6,"q":"What does LDPE stand for in plastic identification?","o":["Low density polyethylene.","High density polyethylene.","Low density polystyrene.","Linear durable polyester."],"a":0,"e":"LDPE refers to low density polyethylene, rather than high density polyethylene or polystyrene."},{"id":272,"s":6,"q":"What does PVC stand for in plastic identification?","o":["Polypropylene vinyl compound.","Polyvinyl chloride.","Polyethylene carbonate.","Plastic viscosity coefficient."],"a":1,"e":"PVC refers to polyvinyl chloride and identifies material type rather than a measurement of viscosity or volume."},{"id":273,"s":6,"q":"What does HDPE stand for in plastic identification?","o":["High density polyethylene.","High density polyester.","High durability polypropylene.","Heat degraded polystyrene."],"a":0,"e":"HDPE refers to high density polyethylene, not a generic description of durable packaging."},{"id":274,"s":6,"q":"What does PET stand for in plastic identification?","o":["Polypropylene thermoplastic.","Polyethylene terephthalate.","Polyvinyl chloride.","Polystyrene compound."],"a":1,"e":"PET refers to polyethylene terephthalate; material identification remains separate from recycled-content or food-safety certification."},{"id":275,"s":6,"q":"What is the purpose of identifying the resin type in plastic packaging records?","o":["To support material identification and appropriate handling.","To replace every measurement of actual plastic material weight.","To determine the corporate ownership of the packaging supplier.","To certify unrestricted food-contact suitability for every resin type."],"a":0,"e":"Recording the resin helps later users of the data understand what material was handled and how it should be assessed."},{"id":276,"s":6,"q":"Why should changes to a packaging label be reviewed before production?","o":["To let internal artwork approval override all legal requirements.","To replace supporting product evidence with preferred advertising language.","To avoid reviewing registration details when business information changes.","To check accuracy before printing a production batch."],"a":3,"e":"Review before printing helps prevent incorrect identity details, outdated claims or unsupported percentages from appearing on an entire batch."},{"id":277,"s":6,"q":"What is the role of packaging specifications in checking labelling compliance?","o":["They replace all applicable statutory standards and technical requirements.","They connect label statements with actual product details.","They establish conformity even when their material information differs.","They determine only the font used for printed information."],"a":1,"e":"The specifications provide a factual basis for checking whether the label describes the actual package accurately."},{"id":278,"s":6,"q":"Why should businesses maintain approved artwork for regulated plastic packaging?","o":["To remove every future need to review packaging information.","To make artwork preferences override the applicable legal provisions.","To control versions and prevent outdated production labels.","To replace technical material records with the printed design."],"a":2,"e":"Version control helps ensure the artwork used on the production line is the reviewed and approved version."},{"id":279,"s":6,"q":"What is the importance of ensuring that packaging information is legible?","o":["Unreadable information always fulfils the applicable packaging-disclosure requirement.","Only decorative advertising text needs to remain clearly readable.","Required information must be readable for its purpose.","Legibility automatically exempts a producer from relevant registration duties."],"a":2,"e":"Information that cannot be read does not serve its identification or verification purpose effectively."},{"id":280,"s":6,"q":"Why should a company verify its packaging labels against the applicable rules?","o":["To assume any recycling symbol fulfils every disclosure.","To replace supporting evidence with a printed slogan.","To verify the required information and claims.","To avoid considering the actual packaging material type."],"a":2,"e":"The assessment should use the applicable rule for the package and claim, rather than a generic symbol alone."},{"id":281,"s":6,"q":"What is the difference between the labelling requirements for recycled and compostable plastics?","o":["Both require identical declarations of virgin resin content.","Recycled plastic must always carry a compostability claim.","Recycled-content information differs from composting-condition information.","Compostable plastic must always claim entirely recycled content."],"a":2,"e":"The label should describe the relevant property of the material and should not confuse recycled content with compostability."},{"id":282,"s":6,"q":"Why must the intended receiving environment be identified on a biodegradable-plastic label?","o":["Performance depends on the specified receiving environment.","Every biodegradable plastic performs identically in every environment.","The environment determines only the product's selling price.","The environment indicates only the company's sales territory."],"a":0,"e":"A claim demonstrated for one receiving environment should not be understood as proven for every other environment."},{"id":283,"s":6,"q":"Why must the stated biodegradation period be included in the applicable biodegradable-plastic label?","o":["It defines the supported time under specified conditions.","It guarantees immediate breakdown after the product is purchased.","It replaces the need to identify the receiving environment.","It establishes how long the manufacturing company has existed."],"a":0,"e":"The stated time connects the claim to the demonstrated degradation performance under the specified conditions."},{"id":284,"s":6,"q":"What information must be specified on the label of a biodegradable plastic product under the 2024 amendment?","o":["The retail price and advertised customer-discount percentage.","The employee headcount and factory working-hour schedule.","The supplier's logo and preferred promotional campaign.","The degradation period and specified receiving environment."],"a":3,"e":"Both elements limit the claim: how long degradation takes and the environment in which the supported performance occurs."},{"id":285,"s":6,"q":"Which Indian Standard is referenced for compostable plastics under the 2024 amendment?","o":["IS 14534 2023.","IS ISO 17088 2021.","IS 17899 T 2022.","ISO 9001 2015."],"a":1,"e":"This is the compostability specification referenced by the stated amendment; the recycled-plastic standard addresses a different subject."},{"id":286,"s":6,"q":"What label is required for plastic packaging or commodities made from compostable plastics under the 2024 amendment?","o":["Compostable only under specified industrial composting conditions.","Compostable immediately in every natural receiving environment.","Compostable in every household without any specific conditions.","Compostable regardless of material testing or certification evidence."],"a":0,"e":"The required wording identifies industrial composting, so it should not be replaced with an unsupported home-composting or marine claim."},{"id":287,"s":6,"q":"What additional labelling requirements may apply to recycled plastic packaging used for food contact?","o":["Applicable FSSAI marking and food-contact labelling requirements.","Only unrelated vehicle registration and driving-licence requirements.","Only household composting and home-gardening labelling requirements.","No additional food-contact information requirements can ever apply."],"a":0,"e":"PWM labelling requirements and applicable food-contact requirements must be considered together for the intended use."},{"id":288,"s":6,"q":"What information about recycled plastic content is relevant to packaging labelling?","o":["Only the company's percentage increase in annual sales.","Supported recycled-content information under the applicable requirements.","Only the percentage of packaging surface carrying artwork.","Only the processor's percentage increase in advertising expenditure."],"a":1,"e":"Any stated recycled-content information should be supported and presented in accordance with the relevant standard and applicable provision."},{"id":289,"s":6,"q":"Which Indian Standard is referenced for recycled plastic packaging under the 2026 amendment?","o":["IS ISO 17088 2021.","ISO 14001 2015.","IS 14534 2023.","IS 17899 T 2022."],"a":2,"e":"The referenced standard addresses recovery and recycling of plastics waste and differs from the compostability standard."},{"id":290,"s":6,"q":"What is the purpose of marking recycled plastic packaging?","o":["To establish compostability without material testing or supporting evidence.","To identify recycled material use under applicable requirements.","To exempt the entity from every relevant EPR obligation.","To authorise every food-contact application without additional conformity checks."],"a":1,"e":"The marking communicates the relevant material information; it does not guarantee that every product is compostable or universally food-safe."},{"id":291,"s":6,"q":"What is the role of a unique number printed on plastic packaging under the 2025 amendment?","o":["A qualifying statutory number provides a conditional disclosure alternative.","Any internal serial number removes every statutory packaging-information requirement.","Any product batch number establishes complete recycled-material content automatically.","Any supplier invoice number replaces access to required product information."],"a":0,"e":"The unique-number route is subject to the conditions stated in the amendment and is not simply any internally generated serial number."},{"id":292,"s":6,"q":"How can a product information brochure provide the information permitted under Rule 11(1A)?","o":["By omitting the information whenever a brochure exists internally.","By keeping the brochure unavailable to the intended information users.","By substituting a promotional slogan for every specified disclosure.","By supplying the specified information in the permitted brochure."],"a":3,"e":"The brochure is a permitted channel for the specified information, subject to the provision's conditions and required communication to CPCB."},{"id":293,"s":6,"q":"What is the role of a QR code in providing packaging information?","o":["To authorise sale of every otherwise prohibited plastic item.","To establish polymer quality without any supporting technical evidence.","To remove every disclosure obligation from the packaging business.","To provide specified information through a permitted mechanism."],"a":3,"e":"The permitted QR mechanism changes how specified information is provided; it does not abolish the underlying information requirement."},{"id":294,"s":6,"q":"How may a barcode be used to provide information required under Rule 11(1)?","o":["By providing specified information under the permitted barcode mechanism.","By directing users only to an unrelated promotional discount.","By printing an arbitrary number without accessible required information.","By exempting the product from all applicable technical standards."],"a":0,"e":"The barcode mechanism must provide the specified information under the applicable conditions, rather than link only to an unrelated promotion."},{"id":295,"s":6,"q":"From which date did the alternative information-provision mechanism under the 2025 amendment become available?","o":["1 January 2024.","1 April 2026.","1 July 2025.","31 December 2022."],"a":2,"e":"The alternative mechanism is available from this stated date even though the amendment itself was notified earlier in 2025."},{"id":296,"s":6,"q":"What change did the 2025 amendment introduce regarding the method of providing certain Rule 11(1) information?","o":["It abolished every packaging identification and material-information requirement permanently.","It permitted specified alternative channels for providing required information.","It required all product packaging to contain no information.","It approved environmental claims without any relevant supporting evidence."],"a":1,"e":"The amendment provides specified alternatives for furnishing information while retaining conditions and the duty to communicate relevant details to CPCB."},{"id":297,"s":6,"q":"What information about carry bag thickness must be provided where applicable?","o":["Only the number of employees working at the supplier.","Carry-bag thickness, where the relevant disclosure applies.","Only the purchase price of the raw material used.","Only the registered address of the final retail customer."],"a":1,"e":"The required thickness information should identify the actual carry-bag specification where that disclosure applies."},{"id":298,"s":6,"q":"Why is the Brand Owner's registration information relevant where required?","o":["It identifies the relevant responsible registered Brand Owner.","It automatically demonstrates fulfilment of every annual compliance target.","It replaces every material specification for the packaging supplied.","It guarantees the food-contact safety of every packaged product."],"a":0,"e":"The information links the package to the relevant registered entity rather than proving that every obligation has already been fulfilled."},{"id":299,"s":6,"q":"Why is the producer's registration number relevant to plastic packaging labelling?","o":["It identifies the relevant responsible registered Producer.","It guarantees biodegradation in every natural receiving environment.","It replaces all applicable technical packaging material standards.","It permits manufacture of otherwise prohibited single-use items."],"a":0,"e":"A registration reference supports verification of the responsible entity; it does not replace technical or product-specific requirements."},{"id":300,"s":6,"q":"What information is required on plastic carry bags under the applicable marking and labelling provisions?","o":["Applicable identity, registration, thickness and certification details.","Only product price, promotional discount and retail sales margin.","Only shop hours, delivery terms and customer support details.","Only a green slogan, recycling picture and brand mascot."],"a":0,"e":"The precise disclosure depends on the applicable bag and provision, including any relevant certification and permitted information mechanism."},{"id":301,"s":7,"q":"Why should a business understand the applicable definitions before preparing its plastic waste compliance report?","o":["All waste-related activities always receive identical accounting treatment.","Definitions matter only after the annual report is audited.","Company terminology overrides the definitions in the operative rules.","Definitions determine the correct classification of reported activities."],"a":3,"e":"Using the wrong definition can cause the same activity or quantity to be assigned to the wrong compliance stream."},{"id":302,"s":7,"q":"What should a company check before classifying a plastic waste quantity as recycled?","o":["Actual processing, registration scope and supporting quantity records.","Only the vehicle colour, collection date and driver's name.","Only the vendor's promise to recycle at a later date.","Only the original purchase value of virgin plastic resin."],"a":0,"e":"The conclusion should follow actual operations and eligible evidence, not merely a collection invoice or a future processing promise."},{"id":303,"s":7,"q":"What should a company check before claiming that plastic packaging has been reused?","o":["Evidence of repeated use without changing the object's structure.","Evidence that the object was melted into new pellets.","Evidence that a recycling certificate was purchased from elsewhere.","Evidence that the unused container was originally purchased correctly."],"a":0,"e":"Records should demonstrate repeated use of the object in a manner meeting the applicable reuse requirements."},{"id":304,"s":7,"q":"Why can reuse and recycling require separate compliance calculations?","o":["Every reused container automatically counts as newly recycled output.","All collected material must be recorded twice for compliance.","They measure distinct activities with different applicable requirements.","One unsupported estimate automatically fulfils both sets of duties."],"a":2,"e":"Separate calculations prevent one activity from being wrongly assumed to fulfil a different obligation automatically."},{"id":305,"s":7,"q":"What is the role of recycling in reducing the demand for virgin plastic?","o":["Recycling requires every new product to contain only virgin material.","Recovered material can substitute for suitable virgin-material uses.","Recycling eliminates the need to assess material quality entirely.","Recycling automatically increases every product's required virgin-material proportion."],"a":1,"e":"Material recovery can provide usable input for suitable new products rather than relying entirely on newly produced resin."},{"id":306,"s":7,"q":"Why is evidence of final processing important in a compliance audit?","o":["Transfers alone do not demonstrate actual eligible processing.","A transport invoice always proves complete recovery of material.","A storage receipt always establishes completed recycling of waste.","A contractor quotation establishes treatment before any operations occur."],"a":0,"e":"The audit needs evidence of the claimed outcome after collection, including the relevant facility and quantity records."},{"id":307,"s":7,"q":"What is the difference between the physical movement of plastic waste and proof of its processing?","o":["Transfer evidence records movement; processing evidence records treatment.","Every vehicle movement establishes another completed recycling operation.","A transport invoice always proves full material-recovery output.","Movement and processing always establish exactly the same outcome."],"a":0,"e":"Waste can move through several handlers before treatment; each movement does not represent a separate processing event."},{"id":308,"s":7,"q":"Why should plastic waste be handled and transported in a traceable manner?","o":["To eliminate any need for the recipient's receipt.","To count each transfer as fresh recycling output.","To verify origin, quantities, transfers and destination.","To make the material's actual destination legally irrelevant."],"a":2,"e":"Traceability supports reconciliation and helps detect unexplained losses, missing receipts or an unverified destination."},{"id":309,"s":7,"q":"What is the role of environmental compliance in plastic waste processing?","o":["Processing must meet applicable approvals and environmental conditions.","Any valuable output automatically permits uncontrolled industrial emissions.","Environmental obligations disappear once a facility receives its first order.","A green label automatically legalises every processing activity performed."],"a":0,"e":"The process must meet its applicable environmental conditions, not merely produce an output with commercial value."},{"id":310,"s":7,"q":"Why should a plastic waste processor maintain accurate operational records?","o":["To substantiate actual inputs, operations and outputs.","To replace monitoring of the actual processing undertaken.","To treat every received kilogram as recovered output.","To establish compliance without any operational processing records."],"a":0,"e":"The records should support a coherent material balance rather than assuming every kilogram received becomes useful output."},{"id":311,"s":7,"q":"What is the importance of checking whether a processor is registered for the relevant activity?","o":["Any registration automatically covers every possible treatment route.","Registration scope must match the relevant processing activity.","A brochure replaces verification of the facility's registered scope.","The actual process never affects eligible compliance treatment."],"a":1,"e":"A facility's registration must cover the process being relied upon; registration for another activity is not enough by itself."},{"id":312,"s":7,"q":"Why should a company verify the validity of recycling certificates it receives?","o":["To assume every printed certificate is automatically legally valid.","To determine validity solely from the certificate's printed colour.","To verify authenticity, eligibility and consistency with records.","To remove all checks on the underlying processing transaction."],"a":2,"e":"A certificate should be checked against the relevant system, issuer, category, period and supporting evidence."},{"id":313,"s":7,"q":"What is the relevance of process loss in plastic recycling operations?","o":["All received material necessarily becomes saleable recycled output.","Losses affect the relationship between input and output.","Process losses are irrelevant to every material-balance calculation.","Any process loss automatically removes all facility-reporting duties."],"a":1,"e":"Contaminants, moisture, rejects and process losses may affect how input relates to eligible processing or recovered output."},{"id":314,"s":7,"q":"Why should a recycler maintain records of input and output quantities?","o":["To select the larger figure without investigating any difference.","To count every receipt as output without processing evidence.","To substitute product selling prices for measured material quantities.","To verify material balances and support processing claims."],"a":3,"e":"Input-output records allow claims to be checked against the facility's actual activity and relevant stock movements."},{"id":315,"s":7,"q":"What is the purpose of using recovered plastic material to produce new products?","o":["To guarantee unrestricted food-contact suitability for every recovered polymer.","To return recovered material to suitable productive use.","To remove every relevant technical requirement for manufactured products.","To turn recovered material into virgin resin by labelling."],"a":1,"e":"The recovered material should be put to an appropriate productive use, subject to quality and application requirements."},{"id":316,"s":7,"q":"Why is material recovery relevant to a circular economy?","o":["It requires every recovered material to be discarded immediately.","It removes all quality requirements for recycled plastic products.","It means burning waste without recovering any useful output.","It retains material value and reduces resource demand."],"a":3,"e":"Keeping material in use preserves value and can reduce the need to replace it with newly extracted resources."},{"id":317,"s":7,"q":"What is the difference between material recovery and energy recovery?","o":["Both operations necessarily produce the same recycled plastic granules.","Material recovery yields materials; energy recovery yields energy.","Material recovery means generating electricity without recovering usable material.","Energy recovery means using an unchanged container repeatedly."],"a":1,"e":"The useful output differs: recovered material in one case and usable heat, electricity or other energy in the other."},{"id":318,"s":7,"q":"Why is the type of processing relevant when assessing EPR compliance?","o":["Processing routes affect relevant obligations and eligible evidence.","Every processing route fulfils every obligation without any distinction.","Collection alone establishes completion of every applicable processing target.","The treatment route matters only when calculating transport distance."],"a":0,"e":"Do not assume that any waste-treatment invoice supports every type of EPR target or certificate claim."},{"id":319,"s":7,"q":"Which broad types of activity are included in the 2026 definition of Plastic Waste Processors?","o":["Recycling and end-of-life disposal of plastic waste.","Sale and purchase of unused virgin plastic resin.","Transport and storage of finished packaged consumer products.","Marketing and advertising of plastic-packaged consumer product brands."],"a":0,"e":"The 2026 definition uses these two broad activity groups; actual registration scope and compliance treatment still need checking."},{"id":320,"s":7,"q":"What is the significance of the 2026 definition of Plastic Waste Processors?","o":["It automatically certifies every waste collector as a recycler.","It covers recycling and specified end-of-life processing entities.","It removes registration requirements for all waste-processing facilities permanently.","It covers only companies manufacturing new virgin plastic packaging."],"a":1,"e":"The definition helps identify the covered processing entities without implying that every collection contractor is a processor."},{"id":321,"s":7,"q":"Why should a company avoid treating every form of plastic waste treatment as recycling?","o":["Every waste-storage activity automatically qualifies as material recycling.","Every collection receipt demonstrates actual recycled-material output quantities.","Every treatment route automatically generates identical recycling compliance credits.","Specific routes and compliance accounting must be distinguished."],"a":3,"e":"Check the specific definitions and EPR provisions, particularly the overlap in the amended general recycling and end-of-life wording."},{"id":322,"s":7,"q":"What is the role of processing records in EPR compliance verification?","o":["They substantiate actual operations and claimed processing quantities.","They automatically substitute for the facility's relevant statutory registration.","They remove all need to check actual processing output.","They serve only advertising and have no verification purpose."],"a":0,"e":"Processing records connect a claimed quantity to actual operations and help distinguish receipt from treatment."},{"id":323,"s":7,"q":"Why should a company retain documents showing the receipt of plastic waste by a processor?","o":["To confirm receipt and reconcile the transferred quantity.","To prove every received kilogram was automatically fully recycled.","To remove the need to identify the receiving facility.","To replace the dispatch documents recording the waste movement."],"a":0,"e":"A receipt confirms a handover stage; further records are needed to establish the claimed final processing outcome."},{"id":324,"s":7,"q":"What is the importance of checking the final destination of plastic waste?","o":["To assume every destination has the necessary operating approvals.","To convert transport distance directly into recycled-material output quantity.","To remove every need to identify the receiving facility.","To verify appropriate facilities and actual processing routes."],"a":3,"e":"The final destination matters because a transfer to an unverified site does not demonstrate compliant treatment."},{"id":325,"s":7,"q":"Why should a business verify a processor's actual processing capability?","o":["Registration or advertising alone does not prove actual capability.","A vendor's brochure establishes unlimited capacity for every processing route.","Every collection contractor can recycle every type of plastic polymer.","The lowest quotation establishes the facility's suitability for every material."],"a":0,"e":"Assess equipment, process, capacity and actual output rather than relying solely on a general marketing claim."},{"id":326,"s":7,"q":"What is the difference between collection capacity and actual recycling output?","o":["Collection capacity and recycling output always equal the advertised quantity.","All waste collected automatically becomes fully recovered recycled plastic material.","Collection capacity concerns gathering; recycling output concerns actual production.","Recycling output is the number of collection vehicles being operated."],"a":2,"e":"A company may collect more than a facility actually recycles, and losses or alternative routes can affect the final figures."},{"id":327,"s":7,"q":"Why should the quantity received by a processor be reconciled with the quantity dispatched?","o":["To automatically report whichever figure produces the largest credit.","To count receipt and dispatch as separate recycling outputs.","To disregard any shortage once the dispatch invoice exists.","To investigate differences and substantiate the quantities transferred."],"a":3,"e":"Differences should be investigated and explained rather than resolved automatically in favour of the larger number."},{"id":328,"s":7,"q":"What is the purpose of maintaining weighbridge records for plastic waste movements?","o":["To certify polymer composition using the total weight alone.","To replace the registration of the relevant processing facility.","To establish only the attendance of the vehicle driver.","To substantiate measured quantities for identified waste movements."],"a":3,"e":"Weight evidence should be linked to the relevant load, date and parties to support a reliable movement record."},{"id":329,"s":7,"q":"Why should the weight of plastic waste be recorded during collection and dispatch?","o":["To substantiate quantities and reconcile the waste movements.","To guarantee industrial compostability of every collected plastic item.","To remove the requirement for any recipient receipt records.","To substitute the product's weight for plastic packaging weight."],"a":0,"e":"Measured quantities help establish a defensible account of how much material entered and left each stage."},{"id":330,"s":7,"q":"What records can help demonstrate the quantity of plastic waste sent for recycling?","o":["Only brochures, slogans, advertisements and promotional campaign material.","Only draft quotations, future promises and unsigned proposals.","Only employee lists, office invoices and staff attendance.","Weighbridge slips, dispatch documents, transport records and receipts."],"a":3,"e":"Use mutually consistent documents rather than relying on an isolated invoice that does not establish receipt or treatment."},{"id":331,"s":7,"q":"Why is traceability important when plastic waste is transferred to a processor?","o":["To exempt every receiving processor from relevant registration requirements.","To treat every transferred load as fully recycled automatically.","To remove the need to record any waste handover.","To link origin, recipient and subsequent handling evidence."],"a":3,"e":"The transfer should remain linked to its source and recipient so subsequent claims can be verified."},{"id":332,"s":7,"q":"How can mixed plastic waste affect processing operations?","o":["Mixing always improves every polymer's performance during recycling operations.","Mixing automatically makes conventional plastic suitable for industrial composting.","Mixing can complicate sorting and reduce recovery quality.","Mixed waste never requires any material-separation or contamination assessment."],"a":2,"e":"Mixed materials can require additional sorting and may reduce the quality or quantity of recoverable output."},{"id":333,"s":7,"q":"What is the importance of identifying contamination in plastic waste?","o":["Contaminants can affect suitability, efficiency and output quality.","Contaminants always increase the amount of usable recycled output.","Contamination has no relevance to any plastic-processing operation.","Contamination automatically demonstrates food-contact safety of the recovered material."],"a":0,"e":"Understanding contaminants helps determine preparation needs, suitability and likely losses in the selected process."},{"id":334,"s":7,"q":"Why should plastic waste be segregated before processing?","o":["To improve compatibility and reduce contamination before processing.","To make all different polymers chemically identical before recycling.","To remove the need to undertake any processing afterwards.","To guarantee zero material loss during every processing operation."],"a":0,"e":"Suitable segregation makes it easier to send compatible materials to the appropriate processing route."},{"id":335,"s":7,"q":"What is the difference between a recycling facility and a waste-to-energy facility?","o":["Both necessarily manufacture identical recovered plastic granules as output.","A recycler only stores waste without any processing activity.","A recycler recovers material; energy facilities recover energy.","An energy facility only refills containers without structural change."],"a":2,"e":"A recycler's material output should not be confused with energy recovered through combustion or another energy process."},{"id":336,"s":7,"q":"Why should a business verify the activity performed by its Plastic Waste Processor?","o":["Every registered processor necessarily performs exactly the same activity.","Any registration makes all processing routes fully interchangeable.","The company's trading name alone establishes its processing activity.","Actual activity determines the relevant route and evidence."],"a":3,"e":"A business name or broad description does not establish which activity the facility actually performs."},{"id":337,"s":7,"q":"What is the role of a Plastic Waste Processor engaged in end-of-life disposal?","o":["To classify every receipt as saleable recycled plastic granules.","To grant every client permanent exemption from all EPR.","To perform the relevant permitted end-of-life disposal route.","To authorise uncontrolled burning of plastic waste outdoors."],"a":2,"e":"The entity undertakes the relevant specified route under applicable conditions and should substantiate the quantities handled."},{"id":338,"s":7,"q":"What is the role of a registered Plastic Waste Processor in recycling?","o":["To convert all collection invoices into unlimited compliance certificates.","To certify every type of plastic as industrially compostable.","To perform registered recycling and substantiate eligible quantities.","To remove every Producer's separate registration and reporting duties."],"a":2,"e":"The registration and records should support the actual recycling claimed, rather than collection or storage alone."},{"id":339,"s":7,"q":"Why should recycling and end-of-life disposal quantities be tracked separately?","o":["Both quantities must always be counted twice for compliance.","Every disposal quantity equals the same recycled-material output quantity.","Separate tracking is unnecessary after any service invoice exists.","They represent distinct streams with different applicable requirements."],"a":3,"e":"Separate records help avoid inappropriate substitution between streams or counting the same material more than once."},{"id":340,"s":7,"q":"Under what conditions can plastic waste be used in road construction as an end-of-life disposal route?","o":["Whenever collected plastic is dumped beside any existing public road.","Whenever a road contractor requests material without reviewing its suitability.","Whenever the supplier describes the plastic as an eco-friendly material.","When applicable guidelines, specifications and legal requirements are met."],"a":3,"e":"Dumping waste beside a road is not the same as its controlled use in road construction under applicable guidelines."},{"id":341,"s":7,"q":"What is waste-to-oil conversion in plastic waste management?","o":["Converting plastic waste into an oil output.","Refilling a container without altering its structure.","Sorting containers according to their printed colours.","Mixing virgin resin with industrial lubricating oil."],"a":0,"e":"The conversion process produces oil; the downstream use and applicable definition determine its relevant treatment under the framework."},{"id":342,"s":7,"q":"How can plastic waste be used in a waste-to-energy process?","o":["By processing suitable waste to recover usable energy.","By storing collected material without any treatment process.","By weighing the material without undertaking any processing.","By transferring material without verifying any subsequent treatment."],"a":0,"e":"The defining outcome is usable energy from suitable waste processing, rather than simply making the waste disappear."},{"id":343,"s":7,"q":"What is co-processing of plastic waste in a cement plant?","o":["Burning waste in open areas outside cement facilities.","Using suitable plastic waste within cement production.","Storing waste near the plant without subsequent processing.","Selling unused carry bags to the factory's employees."],"a":1,"e":"The use occurs within the industrial cement-making process, not as uncontrolled burning outside the facility."},{"id":344,"s":7,"q":"How is the use of plastic waste for energy recovery classified under the 2026 definition of end-of-life disposal?","o":["It is defined exclusively as unchanged-object reuse.","It is expressly included in end-of-life disposal.","It is defined exclusively as temporary waste collection.","It is excluded from every waste-processing activity."],"a":1,"e":"Energy recovery is expressly listed in the specific end-of-life definition; assess the relevant EPR accounting requirement separately."},{"id":345,"s":7,"q":"Is converting plastic waste into feedstock chemicals for producing new plastic treated as recycling or end-of-life disposal?","o":["Storage under the ordinary waste-holding procedure.","Collection under the ordinary waste-transfer procedure.","Recycling under the express feedstock-process exclusion.","Reuse under the unchanged-object use definition."],"a":2,"e":"The express exclusion from end-of-life disposal is important even though the process may start with a thermal or chemical treatment step."},{"id":346,"s":7,"q":"What is the main difference between recycling and end-of-life disposal under the 2026 amendment?","o":["Every movement of waste establishes a completed material-recycling process.","Unchanged-container reuse always qualifies only as end-of-life disposal.","Specified recovery routes exclude the stated feedstock recycling processes.","Open dumping always qualifies as a prescribed material-recycling route."],"a":2,"e":"Use the specific route and obligation when applying the overlapping definitions instead of treating every recovery activity identically."},{"id":347,"s":7,"q":"Does reuse require changing the structure of the object under the 2026 definition?","o":["Yes, the object must always undergo complete melting.","No, the object's structure remains unchanged during reuse.","Yes, the object must always undergo chemical conversion.","Yes, the object must always generate useful energy."],"a":1,"e":"Retaining the object's structure distinguishes reuse from melting, chemical conversion or other reprocessing."},{"id":348,"s":7,"q":"What is the key difference between reuse and recycling under the 2026 amendment?","o":["Reuse always melts waste into new plastic granules.","Recycling only refills unchanged containers with new products.","Both require the waste to undergo industrial composting.","Reuse retains structure; recycling involves waste reprocessing."],"a":3,"e":"The same container used again illustrates reuse, whereas processing its waste into new material illustrates material recycling."},{"id":349,"s":7,"q":"What is the main objective of reusing plastic packaging?","o":["To extend packaging life through repeated suitable use.","To melt every container immediately after its initial use.","To remove all applicable hygiene and product-safety checks.","To convert all conventional containers into compostable material."],"a":0,"e":"Repeated use can reduce the frequency with which new packaging is needed, subject to product safety and applicable requirements."},{"id":350,"s":7,"q":"What is the main objective of recycling plastic waste?","o":["To recover useful value through the defined reprocessing activities.","To establish collection as a substitute for actual processing.","To replace source segregation with uncontrolled mixing of waste.","To classify all discarded material as unused virgin resin."],"a":0,"e":"For specific compliance calculations, do not assume that the general definition makes all forms of recovery interchangeable."},{"id":351,"s":8,"q":"Why should a compliance team maintain a category-wise record of target achievement?","o":["To apply one category's results to every category automatically.","To assess achievement against each category's applicable obligations.","To ignore changes in targets between different financial years.","To count the same certificate repeatedly without any restriction."],"a":1,"e":"Each category's records should show its own requirement, eligible fulfilment and any remaining shortfall."},{"id":352,"s":8,"q":"What is the difference between a target applicable to packaging manufactured and a target applicable to packaging used?","o":["The quantity basis follows the relevant manufactured or used packaging.","Both targets always use the company's annual profit as their basis.","Both targets always use the total weight of the packaged goods.","The difference has no effect on any relevant compliance calculation."],"a":0,"e":"The correct annual quantity basis follows the relevant role and provision rather than whichever total is easiest to obtain."},{"id":353,"s":8,"q":"Why should a business not apply one category's recycled-content percentage to every packaging category?","o":["Every category always has exactly the same applicable percentage.","Entities can choose whichever category's percentage they prefer.","Product price alone establishes the applicable recycled-content percentage.","Prescribed percentages can differ by category and year."],"a":3,"e":"A percentage that is correct for one category or year can be wrong for another, even within the same company."},{"id":354,"s":8,"q":"What is the importance of checking the latest target table before advising a client?","o":["To ensure the oldest published table is always preferred.","To replace statutory figures with current market-average estimates.","To apply the operative percentages, periods and conditions.","To apply another country's targets to Indian business filings."],"a":2,"e":"The relevant table must be read with its conditions, year columns and any applicable amendments."},{"id":355,"s":8,"q":"Why should an entity monitor the target applicable to each financial year?","o":["One year's target always remains unchanged for every future year.","Applicable targets can change between different financial years.","Only calendar years can be used for every applicable target.","Each entity can select any convenient reporting-year percentage independently."],"a":1,"e":"Using a previous year's percentage without checking can understate or overstate the current requirement."},{"id":356,"s":8,"q":"What should a company verify before claiming that it has met a recycled-content target?","o":["The target, quantity basis and eligible fulfilment evidence.","Only the recycling symbol printed on the product packaging.","Only the company's total reported profit for that year.","Only a public promise to increase future recycling activity."],"a":0,"e":"A claim of fulfilment needs both a correct calculation and evidence accepted under the applicable mechanism."},{"id":357,"s":8,"q":"Why should packaging weight and recycled-content percentage be checked together?","o":["A percentage alone always establishes the material quantity in tonnes.","Only packaging surface area determines the recycled-material quantity required.","Any weight basis produces the same required material quantity.","The percentage must use the correct relevant weight."],"a":3,"e":"Applying the right percentage to the wrong weight still produces an incorrect material quantity."},{"id":358,"s":8,"q":"What is the purpose of maintaining invoices for recycled plastic material?","o":["To establish that every purchased kilogram was consumed immediately.","To remove the need for relevant production and inventory records.","To substantiate recycled-material purchases, quantities and traceability.","To relabel every virgin-material purchase as recovered recycled material."],"a":2,"e":"Invoices support purchases, but production, stock and consumption records may also be needed to show actual use."},{"id":359,"s":8,"q":"Why should recycled-content calculations be supported by supplier documentation?","o":["Any supplier slogan automatically establishes the recycled-content percentage.","Documentation automatically removes applicable restrictions on material use.","A supplier can independently choose every client's statutory percentages.","Supplier evidence supports composition and reported material quantities."],"a":3,"e":"Evidence should identify the material and supported content rather than simply repeat an environmental slogan."},{"id":360,"s":8,"q":"How can a change in packaging volume affect the calculation of recycled-content obligations?","o":["The material obligation remains identical regardless of packaging quantity.","Only a change of printed colour affects the calculation.","Changed packaging quantities alter the corresponding mass obligation.","Increased packaging quantities automatically eliminate the applicable content target."],"a":2,"e":"A percentage-based requirement converts into a different mass when the relevant packaging quantity increases or decreases."},{"id":361,"s":8,"q":"What is the importance of accurate data when calculating category-wise recycled-content targets?","o":["Any convenient estimate is acceptable without relevant supporting evidence.","Packaging classification has no effect on the applicable target.","Reliable quantities and categories support accurate target calculations.","Advertising expenditure alone determines the relevant recycled-content obligation."],"a":2,"e":"The calculation depends on reliable category allocations, quantities and the correct applicable percentage."},{"id":362,"s":8,"q":"Why should a business distinguish an actual recycled-content claim from a purchased compliance certificate?","o":["Any purchased certificate proves physical content in every package.","Physical content and certificate-based fulfilment are different claims.","All certificates replace every applicable material-safety requirement automatically.","A compliance certificate and physical composition are always identical."],"a":1,"e":"A permitted certificate mechanism can support compliance without proving that a specific physical package contains recycled material."},{"id":363,"s":8,"q":"What is the purpose of audit and verification of recycled plastic content?","o":["To substantiate content claims and eligible fulfilment quantities.","To approve every supplier declaration without examining supporting evidence.","To replace all underlying records with a general assurance.","To redefine virgin plastic as recycled through verification paperwork."],"a":0,"e":"Verification checks whether the evidence supports the reported content or eligible fulfilment rather than taking declarations at face value."},{"id":364,"s":8,"q":"Why must an exemption be supported by an applicable law, regulation, rule or mandatory Indian Standard?","o":["Higher compliance cost automatically creates a valid legal exemption.","An exemption requires an applicable binding statutory basis.","Customer preference alone establishes an exemption from mandatory requirements.","Every food-contact use automatically qualifies for complete statutory exemption."],"a":1,"e":"Commercial difficulty or a customer's preference for virgin resin is not the same as a binding prohibition on recycled material use."},{"id":365,"s":8,"q":"Why should an entity maintain records of any target it carries forward?","o":["To cancel the outstanding shortfall once it is recorded.","To avoid meeting any future annual obligation or target.","To track eligible balances and subsequent yearly fulfilment.","To count the same later fulfilment against multiple shortfalls."],"a":2,"e":"Keep an opening balance, yearly eligible fulfilment and closing balance so deferred duties remain traceable."},{"id":366,"s":8,"q":"What is the purpose of the carry-forward provision for eligible unfulfilled 2025–26 Category I rigid packaging reuse targets?","o":["To cancel every unfulfilled reuse obligation without further conditions.","To substitute the old shortfall for every later target.","To permit indefinite deferral without any minimum annual fulfilment.","To permit conditional later fulfilment of eligible shortfalls."],"a":3,"e":"The eligible shortfall is deferred subject to the specified conditions; it is not cancelled or substituted for future annual requirements."},{"id":367,"s":8,"q":"What minimum proportion of the eligible carried-forward target must be fulfilled in each year under the 2026 provision?","o":["At least one tenth each year.","At least one quarter each year.","No specified minimum in each year.","At least one third each year."],"a":3,"e":"The provision sets a minimum annual portion of the carried-forward shortfall, in addition to the relevant year's separate target."},{"id":368,"s":8,"q":"Over how many consecutive years may eligible unfulfilled 2025–26 recycled-content targets for food-contact packaging be carried forward?","o":["Up to one consecutive year from 2026–27.","Up to five consecutive years from 2026–27.","Up to seven consecutive years from 2026–27.","Up to three consecutive years from 2026–27."],"a":3,"e":"The permitted window runs from 2026–27 over up to three consecutive years, subject to the minimum annual fulfilment condition."},{"id":369,"s":8,"q":"What is the purpose of the carry-forward provision for unfulfilled 2025–26 recycled-content targets in food-contact packaging?","o":["To permanently exempt all food-contact packaging from recycled-content obligations.","To treat all virgin material as recycled content automatically.","To allow eligible shortfalls to be fulfilled later conditionally.","To cancel all separate targets for the later years."],"a":2,"e":"The provision addresses eligible 2025–26 food-contact shortfalls without permanently waiving recycled-content obligations."},{"id":370,"s":8,"q":"Why must drinking-water packaging be distinguished from other product packaging when calculating certain reuse targets?","o":["Every product always has exactly the same reuse percentage.","Larger-container targets distinguish drinking water from other products.","Drinking-water packaging is always excluded from every rigid-packaging category.","Only the product's brand name determines its reuse target."],"a":1,"e":"For the larger specified containers, drinking water and other products have separate reuse percentages."},{"id":371,"s":8,"q":"Why must the size of Category I rigid packaging be checked when assessing reuse obligations?","o":["The reuse table distinguishes prescribed packaging size bands.","Every packaging size always has the same applicable target.","Size matters only for artwork and product advertising decisions.","All smaller containers automatically qualify as compostable plastic products."],"a":0,"e":"The 0.9 and 4.9 litre or kilogram thresholds distinguish the relevant bands in the stated reuse table."},{"id":372,"s":8,"q":"What reuse target applies in 2026–27 to Category I rigid packaging of at least 4.9 litres or kilograms used for products other than drinking water?","o":["15 percent.","40 percent.","10 percent.","75 percent."],"a":2,"e":"For 2026–27, the stated non-drinking-water band has a 10 percent minimum, unlike the larger drinking-water band."},{"id":373,"s":8,"q":"What reuse target applies in 2026–27 to Category I rigid packaging of at least 4.9 litres or kilograms used for drinking water?","o":["10 percent.","15 percent.","40 percent.","75 percent."],"a":3,"e":"The 75 percent minimum applies to the stated 2026–27 drinking-water band, not every rigid package of any size."},{"id":374,"s":8,"q":"What reuse target applies in 2026–27 to Category I rigid packaging with a volume or weight of at least 0.9 but less than 4.9 litres or kilograms?","o":["5 percent.","30 percent.","15 percent.","75 percent."],"a":2,"e":"The 15 percent minimum applies to the specified middle-size band in 2026–27, subject to the relevant provisions."},{"id":375,"s":8,"q":"What is the purpose of mandatory reuse targets for certain Category I rigid plastic packaging?","o":["To encourage repeated use of qualifying rigid packaging.","To require every container to be melted after use.","To eliminate every applicable hygiene and product-quality requirement.","To substitute reuse for all recycled-content requirements automatically."],"a":0,"e":"Reuse extends the life of qualifying containers while the Brand Owner remains responsible for applicable product quality and requirements."},{"id":376,"s":8,"q":"What is the significance of reporting recycled plastic content in an annual return?","o":["It proves every purchased quantity was immediately consumed.","It replaces the required disclosure of total sales.","It supports verification of reported recycled-material use.","It certifies all rigid packaging as industrially compostable."],"a":2,"e":"The disclosure allows the reported use of recovered material to be assessed against supporting records and applicable requirements."},{"id":377,"s":8,"q":"What is the significance of reporting virgin plastic content in an annual return?","o":["It replaces every required recycled-content disclosure and record.","It grants exemption from all packaging-waste management targets.","It demonstrates that virgin plastic has already been recycled.","It supports composition records and material reconciliation."],"a":3,"e":"Virgin-content data helps explain the overall material composition alongside recycled content and packaging quantities."},{"id":378,"s":8,"q":"What is the purpose of reporting total sales in an annual return?","o":["To disclose only the company's annual product-profit margins.","To replace the need to identify packaging materials.","To establish complete recovery of every product package sold.","To support quantity assessment and prescribed packaging disclosures."],"a":3,"e":"Sales information provides context for the rigid packaging placed into use and must be consistent with the relevant material data."},{"id":379,"s":8,"q":"Why should sales quantities be reconciled with packaging-use data?","o":["To assume all purchases were consumed without any adjustments.","To convert sales revenue directly into plastic material tonnes.","To reconcile packaging quantities with relevant business activity.","To exclude all returned products and stock changes automatically."],"a":2,"e":"Investigate stock, returns, wastage and design changes where a simple purchases-to-sales comparison does not reconcile."},{"id":380,"s":8,"q":"What information must a Brand Owner report about rigid plastic packaging under the 2026 amendment?","o":["Only staff salaries and annual employee-attendance totals.","Only marketing costs and annual consumer-advertising expenditure.","Total sales and virgin and recycled content used.","Only fleet size and waste-collection vehicle running costs."],"a":2,"e":"The required details cover total sales and the use of virgin and recycled plastic content in rigid packaging."},{"id":381,"s":8,"q":"What is the purpose of keeping records of recycled plastic content?","o":["To substantiate recycled-material use and related calculations.","To remove every requirement for material-supplier traceability.","To replace every record describing actual packaging quantities.","To classify all virgin input as recycled material."],"a":0,"e":"Material declarations, purchases and production evidence help substantiate what recycled content was actually used or claimed."},{"id":382,"s":8,"q":"What is the purpose of keeping records of virgin plastic content?","o":["To demonstrate that all virgin input was previously recycled.","To support composition records and material-balance checks.","To replace every supporting record of recycled-material content.","To make the filled product weight equal plastic weight."],"a":1,"e":"Virgin-material records support a complete material balance rather than leaving the unrecycled share unexplained."},{"id":383,"s":8,"q":"How is the recycled-content target for Category III multilayered packaging limited under the 2026 amendment?","o":["It uses only the packaging's paper-layer weight basis.","It uses the packaging's plastic-layer weight basis.","It uses the complete filled-product weight as its basis.","It disregards every individual material layer in the packaging."],"a":1,"e":"The plastic-layer basis prevents paper, foil or other non-plastic layers from being treated as the relevant plastic quantity."},{"id":384,"s":8,"q":"Where must the applicable legal basis for a recycled-content exemption be reported?","o":["Only in the company's own printed advertising brochure.","In the annual return on the prescribed portal.","Only in an undocumented discussion with the supplier.","Only on the packaging supplier's social-media advertising page."],"a":1,"e":"The legal basis must accompany the claim through the prescribed annual-return channel, not remain only an internal assumption."},{"id":385,"s":8,"q":"What must an obligated entity submit when claiming an applicable statutory exemption from recycled-content targets?","o":["The applicable binding provision supporting the claimed exemption.","Only evidence that recycled resin is commercially more expensive.","Only a customer preference letter requesting virgin resin packaging.","Only an unrelated certificate describing the supplier's quality system."],"a":0,"e":"Submit the applicable binding provision and establish its relevance to the application for which the exemption is claimed."},{"id":386,"s":8,"q":"Under what broad circumstance may mandatory recycled-content targets not apply to a particular packaging application?","o":["Virgin resin costs less than the available recycled resin.","The business has fewer customers than its nearest competitor.","Binding requirements disallow recycled content for that application.","The supplier prefers manufacturing with virgin material rather than recycled."],"a":2,"e":"The condition concerns a legally restricted application; higher cost or a supplier preference does not establish the exemption."},{"id":387,"s":8,"q":"Why must recycled-content targets be assessed separately by packaging category?","o":["Prescribed percentages and quantity bases vary by category.","Every category always requires an identical annual content percentage.","Entities may freely select any category's percentage for convenience.","Only product colour determines the legally required recycled percentage."],"a":0,"e":"The category and financial-year columns must be applied separately to the relevant quantities."},{"id":388,"s":8,"q":"What is the difference between recycled plastic content in packaging and the recycling of plastic waste?","o":["Both terms describe only the transportation of collected waste.","A processing payment proves physical content in every package.","Content concerns composition; recycling concerns processing discarded material.","Recycled content describes only the purchase of virgin material."],"a":2,"e":"One concerns the composition of packaging; the other concerns what happens to waste through a processing operation."},{"id":389,"s":8,"q":"How is the recycled plastic content target expressed under the 2026 amendment?","o":["As a percentage of the company's annual net profit.","As a fixed number of employees working at the company.","As a percentage of the product's advertised retail price.","As a percentage of the relevant annual packaging quantity."],"a":3,"e":"Check the role-specific denominator: manufactured, imported or used packaging as stated in the relevant provision."},{"id":390,"s":8,"q":"What is the Category III recycled plastic content target from 2028–29 onwards under the 2026 amendment?","o":["10 percent.","5 percent.","20 percent.","60 percent."],"a":0,"e":"The Category III figure from 2028–29 onward is 10 percent and is subject to its plastic-layer weight basis."},{"id":391,"s":8,"q":"What is the Category II recycled plastic content target from 2028–29 onwards under the 2026 amendment?","o":["5 percent.","10 percent.","20 percent.","60 percent."],"a":2,"e":"The Category II figure from 2028–29 onward is 20 percent rather than the Category I percentage."},{"id":392,"s":8,"q":"What is the Category I recycled plastic content target from 2028–29 onwards under the 2026 amendment?","o":["10 percent.","20 percent.","30 percent.","60 percent."],"a":3,"e":"The Category I figure reaches 60 percent from 2028–29 onward in the stated table."},{"id":393,"s":8,"q":"What is the Category III recycled plastic content target for 2026–27?","o":["10 percent.","5 percent.","20 percent.","40 percent."],"a":1,"e":"Category III remains at 5 percent for 2026–27 in the stated table."},{"id":394,"s":8,"q":"What is the Category III recycled plastic content target for 2025–26?","o":["10 percent.","5 percent.","20 percent.","30 percent."],"a":1,"e":"The stated Category III percentage for 2025–26 is 5 percent, not the later 10 percent figure."},{"id":395,"s":8,"q":"What is the Category II recycled plastic content target for 2026–27?","o":["5 percent.","20 percent.","10 percent.","40 percent."],"a":2,"e":"The Category II percentage is 10 percent for 2026–27 before the later increase shown in the table."},{"id":396,"s":8,"q":"What is the Category II recycled plastic content target for 2025–26?","o":["5 percent.","30 percent.","40 percent.","10 percent."],"a":3,"e":"The Category II percentage for 2025–26 is 10 percent in the stated table."},{"id":397,"s":8,"q":"What is the Category I recycled plastic content target for 2026–27?","o":["10 percent.","20 percent.","60 percent.","40 percent."],"a":3,"e":"The Category I percentage for 2026–27 is 40 percent, compared with 30 percent for the preceding year."},{"id":398,"s":8,"q":"What is the Category I recycled plastic content target for 2025–26?","o":["5 percent.","30 percent.","10 percent.","50 percent."],"a":1,"e":"The Category I percentage for 2025–26 is 30 percent rather than the later 40, 50 or 60 percent figures."},{"id":399,"s":8,"q":"Which packaging categories have mandatory recycled plastic content targets under the 2026 amendment?","o":["Categories I, II and III.","Categories II, III and IV.","Categories III, IV and V.","Categories I, IV and V."],"a":0,"e":"These mandatory percentage tables concern Categories I, II and III, with applicable conditions and exemptions."},{"id":400,"s":8,"q":"What is the purpose of mandatory recycled plastic content targets?","o":["To authorise manufacture of every otherwise prohibited plastic item.","To remove all application-specific material-quality and safety requirements.","To replace every other separate packaging-waste compliance obligation.","To promote recovered-material demand and appropriate recycled-plastic use."],"a":3,"e":"A reliable market for recovered plastic supports recycling, while application-specific legal and safety requirements still apply."},{"id":401,"s":9,"q":"What is the value of a documented audit trail in plastic waste compliance?","o":["It replaces every applicable registration and reporting requirement.","It guarantees that no regulatory inspection can occur.","It permits estimates without retaining any supporting records.","It connects reported claims with verifiable underlying evidence."],"a":3,"e":"The trail should allow a reviewer to follow a reported figure back through calculations to source evidence."},{"id":402,"s":9,"q":"Why should compliance teams check whether reporting formats have changed after an amendment?","o":["Reporting formats remain unchanged regardless of subsequent legal amendments.","Only the company's logo can affect its reporting format.","An old reporting form always overrides newly notified requirements.","Amendments can change fields, forms and required disclosures."],"a":3,"e":"Using an old form can omit a newly required disclosure even when the underlying quantities are otherwise correct."},{"id":403,"s":9,"q":"What should an entity do if the information required for a report is incomplete?","o":["Obtain missing evidence and resolve the information gaps.","Invent plausible figures matching the company's preferred target outcome.","Copy a competitor's figures for the same reporting period.","Omit missing facts while declaring the information fully verified."],"a":0,"e":"Resolve the information gap and check any applicable filing or correction procedure; do not fill missing fields with invented values."},{"id":404,"s":9,"q":"Why should a business maintain evidence of registration and reporting separately?","o":["Registration automatically proves every required annual report was filed.","They demonstrate different compliance facts and submission events.","Any filed report permanently replaces the entity's registration certificate.","Both records always demonstrate exactly the same compliance fact."],"a":1,"e":"Holding registration and completing a particular period's report are different facts that need different evidence."},{"id":405,"s":9,"q":"What is the importance of retaining historical compliance data?","o":["It automatically cancels targets that apply in future years.","It supports historical verification and relevant year-to-year comparisons.","It must always be deleted immediately after each filing.","It is never relevant once the current year begins."],"a":1,"e":"Prior-period records help answer historical queries and explain changes rather than assuming only the latest year matters."},{"id":406,"s":9,"q":"Why should a company document the methodology used to calculate packaging quantities?","o":["To replace actual source records with unexplained estimated quantities.","To make the calculation reproducible and its assumptions verifiable.","To avoid reconciling any subsequent changes in packaging usage.","To make every internal assumption automatically binding on authorities."],"a":1,"e":"Another reviewer should be able to reproduce the total using the recorded assumptions, specifications and source quantities."},{"id":407,"s":9,"q":"What is the purpose of reviewing compliance records before an audit?","o":["To remove evidence that contradicts the declared compliance figures.","To identify gaps and resolve unsupported compliance claims.","To replace the audit with the manager's verbal assurance.","To guarantee approval without producing any underlying supporting records."],"a":1,"e":"Reviewing early gives the team a chance to resolve discrepancies and obtain missing evidence before the audit."},{"id":408,"s":9,"q":"Why should businesses maintain an internal record of filing responsibilities?","o":["To transfer duties to unidentified persons without recorded authorisation.","To substitute internal deadlines for every notified reporting deadline.","To assign filing ownership and prevent missed submissions.","To eliminate the need for reviewing the final data."],"a":2,"e":"The task record should identify who prepares, reviews and submits each relevant filing."},{"id":409,"s":9,"q":"What is the importance of identifying the person responsible for each compliance activity?","o":["It removes all relevant duties from the legal entity.","It replaces every technical check on submitted compliance information.","It supports accountability and timely completion of tasks.","It permits submissions under any person's identity without authority."],"a":2,"e":"A named owner helps prevent tasks from being missed because each person assumes someone else is handling them."},{"id":410,"s":9,"q":"Why should waste collection data be reconciled with processor receipts?","o":["To assume collection always demonstrates complete final material recycling.","To count collection and receipt as two recycling outputs.","To report the larger figure without checking either record.","To verify transfers and investigate unexplained quantity differences."],"a":3,"e":"A collection total and the processor's receipts should be compared so unexplained differences are not carried into reporting."},{"id":411,"s":9,"q":"What is the purpose of verifying the quantity of waste collected from a site?","o":["To establish final processing without obtaining any further evidence.","To identify each polymer from the load's total weight.","To replace every required record of the processor's receipts.","To substantiate the amount collected from that site."],"a":3,"e":"The quantity should be supported by evidence linked to the relevant site and collection event."},{"id":412,"s":9,"q":"Why should a compliance team retain proof of waste collection and transportation?","o":["To establish full recycling of every transported waste load.","To remove the need to verify the actual processor.","To document material movements and support waste traceability.","To avoid recording which facility received the waste material."],"a":2,"e":"Transport records establish part of the chain of custody but should be linked to receipt and processing evidence where required."},{"id":413,"s":9,"q":"What is the importance of checking a contractor's service documentation?","o":["To treat every service invoice as a valid recycling certificate.","To assume every collection contractor holds the required processing registration.","To verify the service against actual work and records.","To remove the need to check waste quantities and transfers."],"a":2,"e":"The records should establish that the claimed service actually occurred and concerned the relevant waste and period."},{"id":414,"s":9,"q":"Why should businesses distinguish their own records from records maintained by a contractor?","o":["Contractor records automatically cancel all duties of the reporting entity.","Every contractor estimate is automatically binding on the competent authority.","The entity must verify its own declarations against evidence.","The entity may never question figures supplied by its contractor."],"a":2,"e":"The company's submission remains its own claim, so contractor data must be reviewed rather than accepted without checking."},{"id":415,"s":9,"q":"What is the purpose of documenting the handover of plastic waste to a collection or processing partner?","o":["To establish that all transferred material was automatically fully recycled.","To remove the need to confirm receipt of the material.","To replace the relevant registration of the receiving waste processor.","To record the transfer's parties, date and quantity."],"a":3,"e":"The handover record connects the waste generator, quantity and recipient at a defined point in the movement chain."},{"id":416,"s":9,"q":"Why should a waste generator segregate plastic waste where required?","o":["To make every plastic item biodegradable through separation alone.","To avoid transferring waste through the applicable handling channels.","To guarantee every separated polymer can be processed together.","To support suitable handling and reduce material contamination."],"a":3,"e":"Keeping relevant streams separate supports appropriate handling and reduces contamination before processing."},{"id":417,"s":9,"q":"What is the role of a waste generator in complying with applicable plastic waste management requirements?","o":["Burn collected plastic outdoors whenever local storage is full.","Dispose of plastic in drains after separating organic waste.","Transfer every duty through an informal verbal contractor agreement.","Follow applicable segregation, storage and handover requirements."],"a":3,"e":"A waste generator must follow the requirements applicable to its own handling and handover, not assume a contractor removes every duty."},{"id":418,"s":9,"q":"Why is coordination between local bodies and other relevant authorities important?","o":["To allow overlapping authorities to ignore every relevant violation.","To remove all locally applicable waste-management enforcement requirements.","To align responsibilities and prevent gaps in implementation.","To substitute informal agreements for the operative statutory provisions."],"a":2,"e":"Clear coordination supports coverage and consistent enforcement where several authorities have related responsibilities."},{"id":419,"s":9,"q":"What types of plastic waste management matters fall within local-body enforcement under the 2026 amendment?","o":["Only incorporation formalities and changes in company directors.","Specified waste-generator management and product-restriction matters.","Only income-tax assessment and deduction of employee taxes.","Only international freight contracts and customs broker appointments."],"a":1,"e":"The 2026 provisions assign enforcement of the specified waste-generator and item-restriction matters within the relevant jurisdiction."},{"id":420,"s":9,"q":"What is the role of local bodies in managing plastic waste generated within their jurisdiction?","o":["Organise local management systems and exercise assigned enforcement.","Guarantee every individual plastic item is recycled after disposal.","Manufacture every packaged consumer product sold within the locality.","Exempt every local commercial establishment from all item restrictions."],"a":0,"e":"The local body has system and enforcement responsibilities rather than a guarantee that every individual item will be recycled."},{"id":421,"s":9,"q":"Why should a company correct material errors identified in its compliance records?","o":["To conceal differences before any regulatory inspection takes place.","To preserve incorrect figures for consistency with old reports.","To assume every error is immaterial without any assessment.","To restore accurate records and correct affected submissions."],"a":3,"e":"An identified material error should be investigated and corrected through the relevant record or filing process."},{"id":422,"s":9,"q":"What is the importance of maintaining a record of regulatory correspondence?","o":["To replace every permit or registration needed for operations.","To make informal advice override operative statutory legal provisions.","To preserve regulatory queries, replies, directions and decisions.","To remove any requirement to follow subsequent authority directions."],"a":2,"e":"The record explains what the authority asked, what the entity replied and which directions or decisions followed."},{"id":423,"s":9,"q":"Why should a business keep supporting evidence for figures reported in an annual return?","o":["To guarantee all unsupported numbers are treated as correct.","To replace the prescribed annual-return submission with internal records.","To permit repeated counting of the same material quantity.","To substantiate reported quantities during relevant verification."],"a":3,"e":"A reported figure should be demonstrable from reliable evidence, not merely repeated across several documents."},{"id":424,"s":9,"q":"What is the role of a Registered Environment Auditor under the 2026 amendment?","o":["Rewrite notified target percentages according to the client's preferences.","Grant every environmental registration without involving the competent authority.","Perform relevant audits through the permitted regulatory mechanisms.","Replace the ministry in notifying new national environmental rules."],"a":2,"e":"The amendment permits Registered Environment Auditors within specified audit and verification mechanisms rather than giving them every regulatory power."},{"id":425,"s":9,"q":"What is the purpose of an audit of plastic waste management information?","o":["To approve every compliance statement without reviewing any evidence.","To remove every future obligation to submit regulatory information.","To assess accuracy, completeness and support for claims.","To convert all estimates automatically into actual measured output."],"a":2,"e":"The audit examines whether claims are complete, accurate and supported by the relevant evidence."},{"id":426,"s":9,"q":"What is the importance of maintaining consistent data across invoices, returns and portal submissions?","o":["Consistency alone proves every underlying transaction actually took place.","Different legal entities can always be treated as one.","Any invoice automatically overrides every conflicting source record available.","It supports a coherent account of relevant transactions."],"a":3,"e":"Consistency is necessary but not sufficient: the figures should also reflect real and substantiated transactions."},{"id":427,"s":9,"q":"Why should an entity retain acknowledgement receipts after submitting reports?","o":["To establish approval of every figure in the report.","To cancel every filing obligation for the following year.","To replace source records supporting the declared material quantities.","To establish receipt and timing of the submission."],"a":3,"e":"Acknowledgements help establish when the report was received; they do not automatically certify every figure as correct."},{"id":428,"s":9,"q":"What is the purpose of reporting through a centralised online portal?","o":["To replace actual processing with an online declaration.","To avoid retaining any underlying compliance evidence locally.","To support prescribed reporting and regulatory verification.","To authorise every plastic product marketed by the entity."],"a":2,"e":"A central system supports structured reporting and verification while the entity retains its underlying evidence."},{"id":429,"s":9,"q":"What is the role of SPCBs and Pollution Control Committees in relevant reporting and oversight?","o":["Assigned reporting functions and oversight within their jurisdiction.","Exclusive national trademark registration for every plastic-packaged product brand.","Direct setting of all domestic packaging material selling prices.","Permanent replacement of every national environmental legislative provision."],"a":0,"e":"The relevant SPCB or PCC receives and oversees the information and activities allocated to it under the framework."},{"id":430,"s":9,"q":"What is the role of CPCB in consolidating implementation information under the PWM framework?","o":["Compile implementation information for the prescribed consolidated report.","Replace every entity's annual return with its advertising brochure.","Audit every household purchase instead of reviewing implementation information.","Issue every business's GST registration and company incorporation certificate."],"a":0,"e":"The central consolidated report brings implementation information together for the prescribed national reporting purpose."},{"id":431,"s":9,"q":"Why should a company maintain evidence supporting an exemption claimed in its annual return?","o":["To make all claimed exemptions permanent without further review.","To avoid identifying the statutory basis for the claim.","To demonstrate that applicable exemption conditions are met.","To replace binding legal evidence with an environmental slogan."],"a":2,"e":"The business should be able to identify the actual applicable provision and demonstrate that its conditions are met."},{"id":432,"s":9,"q":"What is the purpose of documenting recycled plastic content in packaging?","o":["To prove recyclability in every possible collection and processing location.","To establish unrestricted food-contact suitability without any additional evidence.","To substantiate material composition and recycled-content calculations.","To remove every registration duty that applies to the business."],"a":2,"e":"The evidence should support the claimed recycled share for the relevant material, product or reporting calculation."},{"id":433,"s":9,"q":"Why should businesses maintain records of plastic packaging manufactured or used?","o":["To assume every manufactured kilogram was sold without any adjustment.","To remove the need to classify different packaging material formats.","To support relevant quantity calculations and required disclosures.","To substitute the filled product's total weight for plastic weight."],"a":2,"e":"Manufacturing and usage data supply the quantity basis for relevant calculations and annual disclosures."},{"id":434,"s":9,"q":"What is the importance of retaining records of plastic waste sent to another facility?","o":["To treat every transfer as an additional completed recycling operation.","To avoid obtaining any confirmation that the recipient received waste.","To trace transfers and substantiate quantities and destinations.","To establish actual processing solely from dispatch of the material."],"a":2,"e":"Dispatch evidence should connect the material to the recipient and be reconciled with the facility's receipt records."},{"id":435,"s":9,"q":"Why should plastic waste processors maintain records of quantities processed?","o":["To substantiate actual operations and eligible processing claims.","To equate every receipt automatically with saleable recycled-material output.","To replace every record identifying the facility's waste inputs.","To authorise unlimited certificate claims without examining actual output."],"a":0,"e":"Processing quantities should be supported by actual operations, records and relevant material balances."},{"id":436,"s":9,"q":"Why should plastic waste processors maintain records of quantities received?","o":["To establish complete recycling solely from receipt of the waste.","To replace every output record of the recycling facility.","To eliminate the need for evidence of actual processing.","To establish input quantities, sources and material balances."],"a":3,"e":"Receipt records establish what entered the facility and help distinguish input from actual output or processing."},{"id":437,"s":9,"q":"What is the importance of retaining invoices supporting plastic raw material transactions?","o":["To substantiate relevant parties, quantities and material transactions.","To certify all buyers' products as compostable without testing.","To remove every prescribed report applying to those transactions.","To authorise supply to every prohibited-item manufacturing unit."],"a":0,"e":"The invoice helps verify the parties, material and quantity involved rather than proving every downstream use was lawful."},{"id":438,"s":9,"q":"Why should submitted data be checked for completeness before filing?","o":["To guarantee approval regardless of the supporting evidence supplied.","To replace source documents with the completed application form.","To avoid omitted fields and incomplete required disclosures.","To make every missing quantity irrelevant to regulatory assessment."],"a":2,"e":"A pre-filing completeness check helps identify missing fields, attachments or disclosures before submission."},{"id":439,"s":9,"q":"What is the purpose of reconciling an annual return with the underlying business records?","o":["To select whichever quantity gives the lowest compliance obligation.","To avoid investigating differences between invoices and reported returns.","To align reported figures with supported business records.","To assume every purchased kilogram was consumed without adjustments."],"a":2,"e":"The return should be explainable from business records after relevant adjustments, not based on an unexplained chosen total."},{"id":440,"s":9,"q":"Why should a company retain copies of its annual returns?","o":["To avoid retaining any evidence supporting the submitted information.","To establish that every submitted annual-return figure is accurate.","To replace the following year's return with an old submission.","To retain the submitted version for future reference."],"a":3,"e":"A retained return provides the exact submitted version when a later query or comparison arises."},{"id":441,"s":9,"q":"What is the purpose of maintaining a regulatory compliance calendar?","o":["To cancel every obligation once its deadline has passed.","To replace each official notification with an internal timetable.","To measure employee attendance rather than regulatory filing responsibilities.","To track applicable tasks, deadlines and responsible persons."],"a":3,"e":"Linking deadlines to responsibilities and completion evidence supports timely and accountable compliance work."},{"id":442,"s":9,"q":"Why should reporting deadlines be tracked separately for different entity types?","o":["Every entity always uses the same reporting date and form.","Entity roles can have different deadlines and forms.","Company size alone determines every applicable reporting requirement and deadline.","Each supplier independently chooses the statutory deadlines of its customers."],"a":1,"e":"The recycler's annual report and raw-material supplier's reporting requirements should not be treated as having identical deadlines automatically."},{"id":443,"s":9,"q":"By what date must relevant sellers submit their annual transaction report under the 2024 amendment?","o":["30 April each year.","30 June each year.","31 July each year.","31 December each year."],"a":1,"e":"This is the annual transaction-report deadline specified for the relevant sellers under the cited 2024 provision."},{"id":444,"s":9,"q":"What information must sellers of plastic raw material or relevant intermediate material report annually under the 2024 amendment?","o":["Attendance information concerning the seller's permanent and temporary employees.","Transactions involving the covered raw or intermediate materials.","Advertising expenditure concerning the seller's marketing and sales campaigns.","Personal purchases concerning the seller's directors and company shareholders."],"a":1,"e":"The report concerns the covered material transactions rather than unrelated financial or employee information."},{"id":445,"s":9,"q":"By what date must manufacturers and importers of plastic raw material submit their annual report under the 2024 amendment?","o":["30 April each year.","30 June each year.","31 August each year.","31 December each year."],"a":1,"e":"Distinguish this 30 June annual deadline from the separate quarterly reporting timetable."},{"id":446,"s":9,"q":"By what date must the quarterly report for plastic raw material activities be submitted under the applicable 2024 provision?","o":["The first day of the same quarter being reported.","The last day of every fifth financial reporting year.","The last day of the month following the quarter.","The last day of December for every quarterly report."],"a":2,"e":"Each quarter is followed by a reporting month; the provision uses that following month's last day."},{"id":447,"s":9,"q":"Which form is referred to for the quarterly reporting by manufacturers and importers of plastic raw material under the 2024 amendment?","o":["Form I.","Form IV.","Form VI.","Form VII."],"a":3,"e":"Form VII is the specified quarterly form for the relevant plastic raw material manufacturers and importers."},{"id":448,"s":9,"q":"By what date must relevant plastic waste recyclers and processors submit their annual report under the 2024 amendment?","o":["30 April each year.","30 June each year.","31 July each year.","31 August each year."],"a":0,"e":"The stated 2024 annual-report provision for recyclers and processors uses 30 April, not the 30 June deadline used for other roles."},{"id":449,"s":9,"q":"Which form is referred to for the annual reporting by plastic waste recyclers and processors under the 2024 amendment?","o":["Form I.","Form V.","Form VII.","Form IV."],"a":3,"e":"Form IV concerns the stated annual report for recycling or processing of plastic waste."},{"id":450,"s":9,"q":"What is the purpose of an annual report under the PWM Rules?","o":["To replace the registration certificate permanently after first submission.","To authorise every plastic product sold by the entity.","To remove the need to maintain underlying source records.","To provide prescribed yearly information for regulatory assessment."],"a":3,"e":"The annual report makes the period's relevant information available for regulatory assessment and does not replace registration."},{"id":451,"s":10,"q":"What are the key steps a business should follow to assess, document and monitor its PWM compliance obligations?","o":["Buy certificates first, without identifying relevant packaging or obligations.","Apply one assumed obligation to every business and category.","Assess roles, document duties, retain evidence and monitor compliance.","Rely solely on suppliers' promotional descriptions without checking evidence."],"a":2,"e":"A complete process moves from applicability to evidence and ongoing monitoring rather than starting and ending with a certificate purchase."},{"id":452,"s":10,"q":"A company wants to demonstrate compliance during an audit. What records should it maintain for its EPR obligations?","o":["Registrations, packaging data, calculations, certificates, records and returns.","Logos, slogans, advertisements, brochures, testimonials and promotional artwork.","Quotations, promises, forecasts, proposals, estimates and unsigned drafts.","Attendance, salaries, furniture, canteen bills, travel and entertainment."],"a":0,"e":"The records should show how the entity calculated each obligation and the evidence used to support fulfilment."},{"id":453,"s":10,"q":"A plastic waste processor changes its processing activity. Why should its registration and compliance status be reassessed?","o":["Every existing registration automatically covers every new processing activity.","Changing the activity permanently removes every relevant compliance duty.","Only changing the company's name triggers reassessment of processing.","New activities may require different scope, approvals or evidence."],"a":3,"e":"The old scope may not cover the new process, so check the registration, applicable consents and relevant evidence requirements."},{"id":454,"s":10,"q":"A Brand Owner is planning a new packaging design. Which PWM-related requirements should be reviewed before launch?","o":["Colours, photographs, slogans, mascots and preferred advertising campaign language.","Categories, specifications, restrictions, labels and applicable material-use obligations.","Discounts, commissions, sales prizes, loyalty points and promotional giveaways.","Furniture, attendance, meeting rooms, staff uniforms and reception layouts."],"a":1,"e":"Assess the proposed design's actual composition and format before committing to production and printing."},{"id":455,"s":10,"q":"A compliance team identifies inconsistent quantities across invoices and annual returns. What should it do before finalising the filing?","o":["Choose the lowest figure without examining the source records.","Reconcile source evidence and correct the supported figures.","Remove inconsistent invoices before preparing the final reporting figures.","Copy the previous year's quantity despite changed business activity."],"a":1,"e":"The team should explain the differences from source evidence and use supported figures rather than simply selecting the most convenient total."},{"id":456,"s":10,"q":"A company wants to verify the environmental compliance claims of a waste management vendor. What documentary evidence should it request?","o":["A promotional brochure and a green-coloured company logo alone.","Relevant approvals and traceable receipt, processing and output evidence.","A general sustainability promise without any supporting facility information.","A future processing commitment without transaction or operational records."],"a":1,"e":"Evidence should match the facility and actual service claimed, not merely demonstrate that the vendor is an incorporated business."},{"id":457,"s":10,"q":"A local authority and an urban local body have overlapping jurisdiction. What issue should be assessed under the 2026 amendment?","o":["The authority offering the lowest commercial disposal service charges.","The authority assigned enforcement in the overlapping jurisdiction.","Whether jurisdictional overlap automatically cancels all relevant legal duties.","Whether the vendor can choose to ignore both authorities."],"a":1,"e":"The amendment specifies the urban local body's enforcement role where the stated jurisdictions overlap, with separate treatment outside its area."},{"id":458,"s":10,"q":"A company relies on a compliance checklist prepared before the latest amendment. What should be done before using it?","o":["Use it unchanged because it was correct when prepared.","Update it against the applicable amended legal provisions.","Discard all registrations before examining any amended legal provisions.","Assume amendments affect only companies incorporated after the notification."],"a":1,"e":"Check what changed in the applicable provisions and revise the checklist's requirements, dates and document list accordingly."},{"id":459,"s":10,"q":"A business receives conflicting advice about a requirement amended in 2026. Which legal source should be checked first?","o":["The regulator's earlier circular issued before the relevant amendment.","The official Gazette notification containing the amended rules.","The industry's consolidated checklist prepared before the relevant amendment.","The supplier's compliance summary issued before the relevant amendment."],"a":1,"e":"The official operative notification is the primary reference; a summary or social-media interpretation should not override its text."},{"id":460,"s":10,"q":"A company is unsure whether an activity constitutes recycling or end-of-life disposal. Which definitions should it consult?","o":["Only the company's internal product pricing and sales policy.","Amended Rule 3 definitions and applicable EPR provisions.","Only the transport contractor's preferred invoice wording and format.","Only the supplier's chosen terms for marketing its services."],"a":1,"e":"Read the amended definitions together with the particular EPR requirement because the 2026 general and specific wording can overlap."},{"id":461,"s":10,"q":"A Brand Owner cannot reconcile its packaging procurement with its sales data. What records should be reviewed?","o":["Specifications, purchases, production, sales, inventory and relevant adjustments.","Advertisements, campaigns, promotional slogans, customer rankings and brand mascots.","Attendance, salary slips, leave balances, travel and staff appraisals.","Furniture, office rent, reception seating, meeting rooms and stationery."],"a":0,"e":"Differences may arise from stock, production rejects, design changes, returns or timing and should be explained from records."},{"id":462,"s":10,"q":"A company claims a recycled-content exemption because its packaging is used for a regulated application. What legal evidence should support that claim?","o":["A customer letter expressing only a preference for virgin resin.","A supplier quotation showing recycled material has a higher price.","A general statement that every regulated product has complete exemption.","The binding provision restricting recycled content for that use."],"a":3,"e":"The legal evidence must actually restrict recycled content in that application; being regulated in a general sense is not enough."},{"id":463,"s":10,"q":"A business uses packaging for food-contact applications. Which additional regulatory considerations are relevant to recycled plastic?","o":["Only the packaging supplier's preferred colours and artwork choices.","Applicable FSSAI rules, permitted uses and relevant standards.","Only the foreign manufacturer's unsupported general material-marketing slogan.","No checks beyond the printed recycling symbol on packaging."],"a":1,"e":"Food-contact suitability must be assessed under the applicable requirements rather than assumed from a generic recycling claim."},{"id":464,"s":10,"q":"A packaging supplier changes the resin used in a product. Why should the company review its material specifications and records?","o":["Resin changes never affect any packaging-related regulatory records.","Every new resin automatically grants exemption from applicable duties.","Every resin change automatically makes the product industrially compostable.","Resin changes can affect identification, specifications and claims."],"a":3,"e":"A different resin may change identification and material properties even when the package looks the same externally."},{"id":465,"s":10,"q":"A company changes the recycled plastic percentage in its packaging. Which records and compliance calculations may need updating?","o":["Attendance records, staff appraisals, salary deductions and leave applications.","Advertising slogans, social-media captions, campaign budgets and promotional giveaways.","Specifications, supplier evidence, labels, production and content calculations.","Office furniture, reception layouts, meeting schedules and travel bookings."],"a":2,"e":"The revised content should be reflected consistently in the technical, production, supplier and relevant reporting records."},{"id":466,"s":10,"q":"A processor claims that all received plastic waste was recycled. What input-output evidence should be examined?","o":["Inputs, outputs, stock movements, rejects and process losses.","Only the originally agreed waste-collection quotation and sales discount.","Only the number of vehicles listed for collection service.","Only the rent paid for the processor's office premises."],"a":0,"e":"Check whether the claimed output is consistent with inputs after losses, rejects and stock movements are accounted for."},{"id":467,"s":10,"q":"A company receives plastic waste from several locations. What records help establish the origin and quantity of the waste?","o":["Only the receiving company's name and promotional brand logo.","Only one combined estimate without identifying the contributing locations.","Source-wise collection records, measured weights and transfer receipts.","Only an assurance that all incoming loads appeared similar."],"a":2,"e":"Origin and quantity should remain identifiable for each movement so combined totals can be traced to their sources."},{"id":468,"s":10,"q":"A business sells plastic resin and intermediate material used in plastic packaging production. Which definition introduced in the 2026 amendment may be relevant?","o":["Collector moving discarded packaging between waste collection facilities.","Seller of covered raw materials or relevant intermediates.","Brand Owner selling finished goods under a trademark.","Auditor checking the accuracy of environmental compliance records."],"a":1,"e":"The relevant role is seller; the question's reference to it being introduced in 2026 needs the clarification that it existed in 2024."},{"id":469,"s":10,"q":"A company imports plastic raw material rather than finished packaged goods. Which registration and reporting requirements should be assessed?","o":["Only household purchasing conditions for goods imported without commercial use.","Only the internal office procedure for fire-safety practice drills.","No PWM assessment because raw materials are not finished goods.","Covered raw-material importer registration and prescribed reporting requirements."],"a":3,"e":"Raw-material imports are covered by specific provisions and should not be dismissed simply because no filled retail product is imported."},{"id":470,"s":10,"q":"A compliance consultant is assessing a prospective client. What basic information should be collected before determining EPR applicability?","o":["Office layout, furniture, seating, working hours and attendance.","Legal identity, activities, brands, imports and packaging quantities.","Brand mascots, promotional themes, customer reviews and advertising reach.","Supplier discounts, sales commissions, prizes and promotional giveaway plans."],"a":1,"e":"An assessment should start from verified business facts before deciding the role, packaging category or possible exemption."},{"id":471,"s":10,"q":"A company has changed its legal name but not updated relevant registration records. What should it review?","o":["The prescribed process for updating relevant legal-identity records.","Only the company's preferred advertising slogans and promotional templates.","Whether another company has a similar-sounding commercial brand name.","Whether the old name can remain indefinitely without assessment."],"a":0,"e":"The legal-name change should be reconciled across relevant registrations, filings and business records through the prescribed process."},{"id":472,"s":10,"q":"A company reports recycled-content information but omits its total sales information. Which annual-return requirement should be reviewed?","o":["Only the company's internal monthly staff-attendance reporting requirement.","Only the recycling contractor's annual office-electricity reporting requirement.","Only the packaging supplier's pending trademark-registration application requirement.","The rigid-packaging sales and material-content disclosure requirement."],"a":3,"e":"The stated Brand Owner provision requires total sales information alongside the specified virgin and recycled-content details for rigid packaging."},{"id":473,"s":10,"q":"A Brand Owner uses rigid plastic packaging for drinking water. Which factors determine the applicable reuse target?","o":["Retail price, sales commission, advertising spend and market share.","Financial year, size band, product use and exemptions.","Cap colour, label shape, artwork theme and package typography.","Supplier discount, freight charge, payment period and order frequency."],"a":1,"e":"The applicable reuse percentage depends on the table's year and size band, including the distinction for larger drinking-water packaging."},{"id":474,"s":10,"q":"A business receives a recycled-content claim from a packaging supplier without supporting documentation. What should it request?","o":["A verbal reassurance without any traceable supporting material records.","A recycling picture without any declaration of actual composition.","Traceable composition evidence supporting the claimed recycled percentage.","An unrelated sustainability slogan without material or production evidence."],"a":2,"e":"The supplier should provide evidence that supports the actual percentage and material supplied, not simply repeat the claim."},{"id":475,"s":10,"q":"A company records waste dispatched but not the quantity received by its processor. What reconciliation should be performed?","o":["Assume every dispatched kilogram was received and fully recycled.","Record dispatch and receipt as two separate recycling outputs.","Match dispatch evidence with receipts and investigate differences.","Report the larger quantity without examining any source evidence."],"a":2,"e":"Receipt confirmation is needed to establish what arrived; investigate differences instead of assuming dispatch equals receipt or recycling."},{"id":476,"s":10,"q":"A company claims that reusing a container is the same as recycling it. What is the key distinction between the two activities?","o":["Both activities always require melting the original plastic container.","Reuse means converting containers into oil through chemical treatment.","Reuse retains the object; recycling reprocesses waste material.","Every unchanged refill automatically qualifies as chemical material recycling."],"a":2,"e":"The key issue is whether the object's structure is retained during repeated use or the waste is reprocessed."},{"id":477,"s":10,"q":"A processor converts plastic waste into feedstock chemicals for producing new plastic. How is this activity classified under the 2026 amendment?","o":["Recycling under the express feedstock-process exclusion.","Storage under the temporary material-holding procedure.","Reuse under the unchanged-object use definition.","Collection under the ordinary waste-transfer procedure."],"a":0,"e":"The stated feedstock process falls within the explicit recycling exclusion from the end-of-life definition."},{"id":478,"s":10,"q":"A business treats all plastic waste sent for energy recovery as recycling. Which distinction under the 2026 amendment should it reconsider?","o":["Automatic fulfilment of every material-recycling requirement through energy recovery.","Automatic classification of all energy processes as unchanged-container reuse.","Energy recovery's specific end-of-life and EPR accounting treatment.","Exclusive reliance on transport distance to classify the treatment."],"a":2,"e":"The specific route and EPR provision must be checked; energy recovery should not automatically be substituted for every material-recycling requirement."},{"id":479,"s":10,"q":"A company wants to provide certain packaging information through a QR code. Which amendment permits this alternative mechanism?","o":["The original Plastic Waste Management Rules 2016.","The plastic carry-bag thickness amendment issued in 2021.","The Plastic Waste Management Amendment Rules 2025.","The rigid-packaging reuse-target amendment issued in 2026."],"a":2,"e":"The 2025 amendment provides the alternative information mechanism, available from its stated 1 July 2025 date."},{"id":480,"s":10,"q":"A packaging label contains outdated registration details. What should the business review before the next production run?","o":["Current disclosures, registration details and approved production artwork.","Only the printed colours selected for the package design.","Only the buyer's preferred discount for the next order.","Whether the supplier can alter old certificates without approval."],"a":0,"e":"Update and verify the required information before producing another batch rather than carrying an outdated registration detail forward."},{"id":481,"s":10,"q":"A retailer receives carry bags without sufficient thickness information. What should it verify before distribution?","o":["Relevant material, thickness or GSM and supporting evidence.","Only the supplier's preferred bag colour and brand artwork.","Only the supplier's freight charges and free-delivery order value.","Only the number of handles attached to each bag."],"a":0,"e":"Establish which specification applies to the bag type and obtain reliable measurement or supporting technical evidence."},{"id":482,"s":10,"q":"A manufacturer plans to sell plastic carry bags. Which two physical specifications should it verify?","o":["Manufacturer's corporate age and office floor-area measurement specifications.","Applicable conventional-bag thickness and non-woven-bag GSM specifications.","Customer's personal income and total purchase-value measurement specifications.","Artwork's printed colour count and promotional slogan-length specifications."],"a":1,"e":"Thickness and GSM are different measures for the relevant bag types, not two interchangeable numbers or universal tests for all bags."},{"id":483,"s":10,"q":"A raw material supplier discovers that a prospective buyer manufactures prohibited single-use plastic items. What restriction is relevant?","o":["The applicable restriction on supply to prohibited-item manufacturers.","An automatic exemption whenever the buyer makes cash payment.","A general permission arising solely from owning factory premises.","An automatic exemption whenever market demand exceeds available supply."],"a":0,"e":"A business should assess the supply prohibition rather than treating a registered buyer or cash payment as permission for a banned use."},{"id":484,"s":10,"q":"A plastic raw material supplier receives an order from an unregistered buyer. What should it check before supplying the material?","o":["Only whether the customer agrees to make advance payment.","Only whether the customer uses a professional-looking company logo.","Only whether the customer promises future registration after delivery.","Applicable buyer registration and whether supply is permitted."],"a":3,"e":"The legal permissibility of supply depends on the applicable buyer-registration and intended-use requirements, not only payment terms."},{"id":485,"s":10,"q":"A business has missed a compliance reporting deadline. What should its compliance team review first?","o":["Whether the company can delete the missed reporting period.","Whether the supplier agrees to disregard the filing deadline.","Whether an older return can be labelled as current.","The deadline, valid extensions and prescribed corrective process."],"a":3,"e":"First establish the actual requirement and current filing route, including any valid extension and prescribed corrective steps."},{"id":486,"s":10,"q":"A company uses multilayered packaging. Which packaging component's weight is relevant to the recycled-content target under the 2026 amendment?","o":["The weight of paper layers in the packaging.","The weight of plastic layers in the packaging.","The weight of aluminium layers in the packaging.","The weight of the product inside the packaging."],"a":1,"e":"The Category III recycled-content basis concerns the plastic portion, excluding the non-plastic layer weights from that basis."},{"id":487,"s":10,"q":"A company wants to claim an exemption from a recycled-content target. What evidence should it identify?","o":["Only a supplier letter stating that virgin material costs less.","The binding provision disallowing recycled content for that application.","Only a customer statement expressing a general material-quality preference.","Only an internal forecast estimating the product's future sales quantities."],"a":1,"e":"The exemption needs an applicable binding prohibition or condition, not merely a business preference for virgin material."},{"id":488,"s":10,"q":"A Brand Owner outsources packaging manufacturing. Why should it review the packaging data supplied by its manufacturer?","o":["To transfer every Brand Owner duty to the manufacturer automatically.","To assume manufacturing arrangements remove all relevant EPR applicability.","To classify all outsourced packaging as exempt from the framework.","To substantiate packaging data and the applicable compliance calculations."],"a":3,"e":"Outsourcing does not make the supplied figures self-verifying; the Brand Owner needs reliable packaging information for its own applicable duties."},{"id":489,"s":10,"q":"An Importer has incomplete data on plastic packaging accompanying imported goods. What records should it examine?","o":["Only office rent receipts, premises photographs and utility bills.","Only supplier advertising brochures, marketing slogans and promotional material.","Only employee numbers, attendance information and annual salary records.","Import documents, supplier specifications, packing details and declarations."],"a":3,"e":"Use the available shipment, supplier and technical records to establish the plastic packaging accompanying the imported goods."},{"id":490,"s":10,"q":"A company reports the same packaging weight for two different financial years despite a major change in sales. What should be reviewed?","o":["Only the previous year's total without checking current records.","Each year's sales, weights, methodology and stock movements.","Only the company's logo and preferred advertising colour scheme.","Only the bank's current interest rate and loan limit."],"a":1,"e":"A major sales change should prompt review, although inventory and other justified factors may explain why packaging totals differ from expectations."},{"id":491,"s":10,"q":"A plastic waste processor provides a certificate but no supporting transaction records. What should the compliance team verify?","o":["Only whether the document displays a printed coloured stamp.","Only whether the issuing vendor offers a commercial discount.","Authenticity, eligibility and supporting processing or transaction evidence.","Only whether the certificate uses thick premium printing paper."],"a":2,"e":"A certificate should be supported by a verifiable eligible transaction or processing history rather than accepted solely because it looks official."},{"id":492,"s":10,"q":"A supplier describes a product as biodegradable. What labelling and technical details should be checked?","o":["Only green colouring, surface texture and packaging artwork style.","Only whether the finished item can be torn by hand.","Certification, testing, degradation conditions and required label details.","Only the supplier's biodegradable slogan without technical supporting records."],"a":2,"e":"Check the supported period and environment for degradation as well as applicable certification and required disclosures."},{"id":493,"s":10,"q":"A supplier describes a product as compostable. What compliance information should be verified?","o":["Only the supplier's promise of immediate outdoor decomposition.","Certification, compostability standards and relevant labels.","Only the product's appearance suggesting a plant-based source.","Only an ordinary invoice listing the product's selling price."],"a":1,"e":"The claimed material must meet the relevant standard and certification conditions, including the industrial-composting label where required."},{"id":494,"s":10,"q":"A company claims that its packaging contains recycled plastic. What supporting information should be requested?","o":["Only a recycling symbol printed on the outer packaging.","Composition, claimed percentage and traceable supporting material evidence.","Only a corporate sustainability promise without product-specific supporting records.","Only the selling price printed on the packaged product."],"a":1,"e":"Traceability should connect the claimed composition with the supplied material and relevant manufacturing records."},{"id":495,"s":10,"q":"A business changes from rigid packaging to flexible packaging. What should be reviewed for EPR compliance?","o":["Classification, applicable targets and relevant quantity or reporting records.","Only the promotional slogan used to advertise the packaged product.","Only whether the supplier continues trading under the same name.","Nothing, because every plastic format always has identical compliance requirements."],"a":0,"e":"A switch in format can change category-specific requirements and the evidence used in the relevant calculations."},{"id":496,"s":10,"q":"A company uses three different types of plastic packaging. Why should each type be classified separately?","o":["Every packaging format must always be classified as Category I.","Different constructions can create different categories and obligations.","Different materials automatically share one target when sold together.","Only the finished product's selling price determines its packaging category."],"a":1,"e":"Separate classification prevents different materials and obligations from being incorrectly merged into one total."},{"id":497,"s":10,"q":"A plastic waste processor claims to be registered. What registration details should a compliance team verify?","o":["Only the company logo, printed slogan and promotional artwork.","Only the salesperson's verbal assurance and preferred contact details.","Legal identity, current registration, facility and relevant activity.","Only an old unsigned quotation and supplier discount offer."],"a":2,"e":"The current registered scope should match the actual process and facility whose work will support the claim."},{"id":498,"s":10,"q":"A company manufactures plastic packaging for another brand. Which business role should be assessed under the PWM Rules?","o":["The household-consumer role under personal product consumption activities.","The local-authority role under municipal waste-management enforcement functions.","The environment-auditor role under independent compliance verification activities.","The Producer role under the applicable activity definitions."],"a":3,"e":"Manufacturing for another brand can still fall within the Producer assessment; the commercial arrangement should be reviewed."},{"id":499,"s":10,"q":"An Indian company imports products packed in plastic. Which PWM-related applicability questions should it assess?","o":["Importer applicability, packaging quantities and relevant compliance requirements.","Only the overseas supplier's website appearance and preferred artwork.","Only the imported products' price and expected commercial margin.","No PWM assessment because packaging merely accompanies imported goods."],"a":0,"e":"The presence of packaging around imported goods can be relevant even where the imported product itself is not plastic."},{"id":500,"s":10,"q":"A company sells packaged products under its own brand. What should be checked to determine its EPR obligations?","o":["Only the company logo and its preferred green colour.","Brand Owner status, packaging and applicable duties or exemptions.","Only whether packaging manufacture has been assigned to another business.","Only whether the business already files its GST returns."],"a":1,"e":"Assess the actual role, materials, quantities and applicable conditions rather than assuming that GST payment or outsourcing settles EPR compliance."}]

export const PWM_TOTAL = 500
